INSERT INTO m224_art VALUES
(1,-1,$m224$المادة الأولى إصدار$m224$,$m224$يعمل بأحكام القانون المرافق في شأن الإيداع والقيد المركزي والتسوية والمقاصة في الأوراق المالية. ويلغى كل حكم يخالف أحكامه.$m224$,'d450eac25de86c7a8f33d202fded5849'),
(2,-1,$m224$المادة الثانية إصدار$m224$,$m224$في تطبيق أحكام القانون المرافق ولائحته التنفيذية والقرارات المنفذة له يقصد بـ الوزير المختص رئيس مجلس الوزراء وبـالهيئة الهيئة العامة للرقابة المالية.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'86cb7c775abf4175fee08da58f5ce0cd'),
(3,-1,$m224$المادة الثالثة إصدار$m224$,$m224$يصدر رئيس مجلس الوزراء بناء على عرض رئيس مجلس إدارة الهيئة العامة للرقابة المالية وبعد أخذ رأي مجلس الإدارة، اللائحة التنفيذية للقانون المرافق خلال مدة لا تجاوز أربعة أشهر من تاريخ العمل به.
وإلى أن تصدر اللائحة التنفيذية والقرارات المنفذة للقانون المرافق، يستمر العمل بالأحكام والقواعد والنظم القائمة في تاريخ العمل به فيما لا يتعارض مع أحكامه.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'56e3b5c17b936d60a4d09174e108a4fb'),
(4,-1,$m224$المادة الرابعة إصدار$m224$,$m224$على الشركات القائمة في تاريخ العمل بهذا القانون والتي تزاول نشاط الإيداع أو القيد المركزي أو المقاصة أو التسوية في الأوراق المالية أو نشاط أمناء الحفظ أن توفق أوضاعها وفقا لأحكامه خلال ستة أشهر من ذلك التاريخ.
وعلى الشركات التي أصدرت أوراقا مالية قبل تاريخ العمل بهذا القانون الالتزام بأحكام القانون المرافق خلال مدة لا تجاوز سنة من ذات التاريخ.$m224$,'3ff7d7f84aac4281662508a30d4a3165'),
(5,-1,$m224$المادة الخامسة إصدار$m224$,$m224$يصدر رئيس مجلس الوزراء قرارا بالمراحل والمواعيد التي يتم خلالها إيداع وإلغاء صكوك الأوراق المالية التي يتعين إيداعها وقيدها طبقا لأحكام القانون المرافق لدى شركة الإيداع والقيد المركزي، وعلى الشركة اتخاذ التدابير المناسبة للالتزام بتلك المواعيد.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'49f1a2639e046826b2a5622b77d6059f'),
(6,-1,$m224$المادة السادسة إصدار$m224$,$m224$تسري أحكام قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981 وقانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992 فيما لم يرد به نص خاص في القانون المرافق.$m224$,'dddf125bba5778dbe89ce9532436e638'),
(7,-1,$m224$المادة السابعة إصدار$m224$,$m224$ينشر هذا القانون في الجريدة الرسمية، ويعمل به من أول الشهر التالي لمضي شهر على تاريخ نشره. يبصم هذا القانون بخاتم الدولة، وينفذ كقانون من قوانينها.$m224$,'29abe84fc242432dc44b69addc19d31e'),
(1,0,$m224$المادة 1$m224$,$m224$يقصد بالشركة كل شركة مرخص لها بمزاولة نشاطي الإيداع والقيد المركزي للأوراق والأدوات المالية، كما يقصد بأعضاء الإيداع المركزي الجهات المنصوص عليها في المادة (19) من هذا القانون.
وفيما لم يرد في شأنه نص خاص في هذا القانون، تسري جميع الأحكام المتعلقة بالأوراق المالية وشركات الإيداع والقيد المركزي لها والواردة في هذا القانون على كل ما يتعلق بالعقود الآجلة والأوراق والأدوات المالية الحكومية وشركات الإيداع والقيد المركزي لها، وذلك فيما لا يتعارض مع طبيعة أي منها.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'3e5ff9cdf02f81682eba016876e8f1bc'),
(2,0,$m224$المادة 2$m224$,$m224$يقصد بنشاط الإيداع المركزي كل نشاط يتناول إيداع وحفظ الأوراق المالية وإجراء المقاصة وتسوية المراكز المالية الناشئة عن عمليات التداول ونقل ملكية الأوراق المالية عن طريق القيد الدفتري، بما في ذلك:
1 - حفظ الأوراق المالية لدى الشركة أو لدى إحدى الجهات المرخص لها بذلك.
2 - نقل ملكية الأوراق المالية التي تم التعامل عليها عن طريق أعضاء الإيداع المركزي وذلك بالقيد الدفتري.
3 - قيد حقوق الرهن على الأوراق المالية.
4 - جراء المقاصة وتسوية المراكز المالية الناشئة عن تداول الأوراق المالية.
5 - حفظ وتسوية الأوراق والأدوات المالية الحكومية وفقا للقواعد التي يضعها مجلس إدارة الهيئة، بعد أخذ رأي البنك المركزي المصري ووزارة المالية.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'ceaf395c2e8be70f628f56412a59b8a9'),
(3,0,$m224$المادة 3$m224$,$m224$يقصد بنشاط القيد المركزي كل نشاط يتناول إمساك سجلات بملكية الأوراق المالية وحقوق الرهن المقيدة عليها، بما في ذلك:
1 - إمساك السجلات بأسماء ملاك الأسهم وغيرها من الأوراق المالية وما يرد عليها من حقوق وتصرفات.
2 - توزيع المستحقات الناتجة عن الأوراق المالية التي يتم حفظها لدى الشركة، بما في ذلك الأصل والعائد وتوزيعات الأرباح وقيم الاسترداد ومدفوعات إعادة الهيكلة.
3 - نشر التقارير والمعلومات التي تفصح عنها الجهات التي تصدر الأوراق المالية أو المتعلقة بتلك الأوراق
4 - تقديم الخدمات المتصلة بإصدار الأوراق المالية بالنيابة عن المصدر.
5 - جراء ما يلزم لاستبدال الأوراق المالية عند إعادة هيكلة الجهة المصدرة.$m224$,'350c52e0b27b5c39fb8f0f9f3c049caf'),
(4,0,$m224$المادة 4$m224$,$m224$لا تنتقل ملكية الأوراق المالية التي تم إيداعها لدى الشركة إلا بإتمام تسوية العمليات التي أجريت عليها.$m224$,'f040a16e3023dbc02eaa6e78cd1c6da3'),
(5,0,$m224$المادة 5$m224$,$m224$لمالك الورقة المالية جميع الحقوق التي تنتجها ملكيته لها، ويتم إيداع وقيد الورقة باسمه.
ومع ذلك يجوز أن تودع الأوراق وتقيد باسم شخص، ويكون لشخص آخر أو أكثر الحقوق التي تنتجها، ويطلق على الأول اسم المالك المسجل وعلى الثاني اسم المالك المستفيد وفي هذه الحالة يلتزم المالك المسجل بالتزامات أمناء الحفظ المنصوص عليها في هذا القانون.$m224$,'b0d37235bf32e352c877a171de492cc6'),
(6,0,$m224$المادة 6$m224$,$m224$لا يجوز أن يكون مالكا مسجلا إلا بنوك الإيداع والجهات التي تمارس أنشطة أمناء الحفظ أو إدارة محافظ الأوراق المالية أو أي نشاط آخر يصدر به قرار من الوزير المختص بعد أخذ رأي الهيئة.
ويقصد ببنوك الإيداع البنوك التي تصدر شهادات إيداع يتم قيدها وتداولها في بورصات الأوراق المالية المحلية أو الدولية في مقابل ملكيتها ملكية مسجلة لأوراق مالية.
وعلى كل مالك مسجل أن يقيد اسمه وبياناته في سجل تعده الهيئة لهذا الغرض، ويحدد مجلس إدارة الهيئة قواعد وإجراءات القيد فيه.$m224$,'90f6774a7baeed6eb1de306fcb699fa6'),
(7,0,$m224$المادة 7$m224$,$m224$يكون تعامل مصدر الورقة المالية مع المالك المسجل، ويكون تعامله على هذا النحو مبرئا لذمته. ويلتزم المالك المسجل بأن يمكن المالك المستفيد من جميع الحقوق التي تنتجها الورقة بما في ذلك الحصول على الحقوق المالية التي تستحق عنها والمعلومات المتعلقة بها التي يفصح عنها مصدر الورقة، كما يلتزم بتعليمات المالك المستفيد بالنسبة إلى التصويت عن الورقة والتصرف فيها، وتؤول حصيلة التصرف إلى المالك المستفيد.
وفي جميع حالات انقضاء شخصية المالك المسجل أو إفلاسه، ينتقل تسجيل الأوراق المالية إلى المالك المستفيد.$m224$,'99bab706024140e85bb2210320907912'),
(8,0,$m224$المادة 8$m224$,$m224$تتماثل الأوراق المالية التي تم إيداعها لدى الشركة والمزايا التي تنتجها وتحل محل بعضها إذا كانت من ذات النوع والإصدار والعملة، ولا يكون لأي عضو من أعضاء الإيداع المركزي التمسك بحق أو التزام على أوراق بذاتها.
وتسري أحكام الفقرة السابقة بالنسبة إلى الملاك المستفيدين لأوراق مالية لها مالك مسجل واحد. ويلتزم المالك المسجل بالتصويت عن كل مالك من الملاك المستفيدين وفقا للتعليمات التي تلقاها منه.$m224$,'fc0e3e00230f640dc7b4bf1775d6c466'),
(9,0,$m224$المادة 9$m224$,$m224$للشركة أن تباشر نشاطها بالنسبة للأوراق المالية بما في ذلك الأوراق المالية الأجنبية، والتي يشترط فيها أن تكون مقيدة في بورصة الأوراق المالية بالدولة التي صدرت بها.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'ef0de3955c218ba0cfa1df93bd8f04a9'),
(10,0,$m224$المادة 10$m224$,$m224$لا يجوز لممثلي أعضاء مجلس إدارة الشركة والعاملين بها وأزواجهم وأولادهم القصر التعامل في الأوراق المالية، إلا بعد موافقة مجلس إدارة الشركة. ويصدر بتحديد قواعد وإجراءات الموافقة قرار من الهيئة وفقا للقواعد التي تحددها اللائحة التنفيذية.$m224$,'26380cd53b93a76e16657cb7b33e225e'),
(11,0,$m224$المادة 11$m224$,$m224$يجب أن تودع لدى الشركة الأوراق المالية المقيدة في إحدى بورصات الأوراق المالية وجميع الأوراق المالية التي تصدرها أي شركة إذا طرحت أوراقا مالية لها في اكتتاب عام. ويجوز إيداع غير ذلك من الأوراق المالية.
وفي جميع هذه الحالات يكون قيد الأوراق المودعة وإجراء المقاصة والتسوية للعمليات التي تتم عليها من خلال الشركة.$m224$,'f019f8097d4026abe40c766fcde3028d'),
(12,0,$m224$المادة 12$m224$,$m224$يمتنع التعامل على الأوراق المالية المودعة أو اقتضاء الحقوق المترتبة عليها إلا عن طريق القيد الدفتري لدى الشركة. ولا يجوز سحب الأوراق المالية بعد إيداعها إلا في الحالات التي يصدر بها قرار من رئيس مجلس إدارة الهيئة.$m224$,'0052c456709043b05582b741ab902154'),
(13,0,$m224$المادة 13$m224$,$m224$عند إلغاء صكوك الأوراق المالية وفقا للقواعد التي يحددها قرار من الوزير المختص يحل محلها صك واحد عن كل إصدار للأوراق يودع لدى الشركة، على أن يدون فيه عددها ونوعها وقيمتها وغير ذلك من البيانات التي تحددها اللائحة التنفيذية.$m224$,'9b9656458b067bb7112aceed89b527dd'),
(14,0,$m224$المادة 14$m224$,$m224$تقوم الشركة بإجراء عمليات المقاصة في الأوراق المالية لحساب أعضاء الإيداع المركزي وذلك بهدف تحديد صافي حقوق والتزامات كل منهم، كما تقوم الشركة بإجراء عمليات تسوية المراكز المالية الناشئة عن تداول الأوراق المالية.
وتبين اللائحة التنفيذية ما تشمله المقاصة والتسوية من عمليات وماتتطلبه من إجراءات.$m224$,'73a75dcca82b56a93e9031700d58e84f'),
(15,0,$m224$المادة 15$m224$,$m224$تجرى الشركة عمليات المقاصة والتسوية في الأوراق المالية على أساس التسليم مقابل سداد الثمن، ويجب ألا تتجاوز الفترة بين إجراء عملية التداول وإتمام التسوية الخاصة بها المدة التي يصدر بتحديدها قرار من مجلس إدارة الهيئة.$m224$,'0e6f110e2190684d5ba583b512089a05'),
(16,0,$m224$المادة 16$m224$,$m224$على مجلس إدارة الشركة أن يصدر بعد موافقة الهيئة قرارا بالنظم اللازمة لضمان تنفيذ أعضاء الإيداع المركزي لالتزاماتهم المتعلقة بالتسوية في الأوراق المالية، وله أن يلجأ في ذلك إلى كل أو بعض الوسائل الآتية:
1 - اشتراط قيام العضو بتقديم كفالة من الغير.
2 - تعيين حد أقصى لالتزامات العضو النقدية عن معاملاته مع الشركة أو من خلالها.
3 - تحديد قواعد وإجراءات تصفية العمليات التي لا تتم تسويتها.
4 - وضع نظام لتسليف الأوراق المالية بين أعضاء الإيداع المركزي.$m224$,'722be3801d71c2d50a43f837ff5c92a6'),
(17,0,$m224$المادة 17$m224$,$m224$على الشركة أن تقوم بحفظ الأوراق المالية لديها أو لدى إحدى الجهات المرخص لها بممارسة نشاط أمناء الحفظ، وأن تودع الأموال الخاصة بأعضاء الإيداع المركزي لدى أحد البنوك الخاضعة لإشراف البنك المركزي المصري.$m224$,'9b5e3b5595931891f0807f436fb03191'),
(18,0,$m224$المادة 18$m224$,$m224$على الشركة أن تنشئ وتدير صندوقا لضمان الوفاء بالالتزامات الناشئة عن عمليات الأوراق المالية يلتزم الأعضاء بالاشتراك فيه، ويصدر بنظامه وبقواعد الاشتراك فيه وبمقابل التأخير عن الوفاء بالاشتراك في ميعاد استحقاقه، قرار من مجلس إدارة الهيئة بناء على عرض مجلس إدارة الشركة.
ويعاقب بغرامة قدرها (1%) من قيمة المبالغ موضوع الالتزامات المتأخرة والناشئة عن عمليات الأوراق المالية، وذلك عن كل يوم من أيام التأخير في الوفاء بهذه الالتزامات.
*معدلة بموجب قانون رقم 143 لسنة 2004.$m224$,'e9fb86a0e89702831f05681a6d2c2c27'),
(19,0,$m224$المادة 19$m224$,$m224$يجب أن يكون أعضاء الإيداع المركزي من بين الجهات الآتية:
1 - البنوك وفروع البنوك المسجلة لدى البنك المركزي المصري.
2 - الشركات العاملة في مجال الأوراق المالية وفقا للأنشطة التي يحددها مجلس إدارة الهيئة.
3 - الشركات والجهات الأجنبية التي تمارس نشاط الإيداع المركزي للأوراق المالية، بشرط أن يكون مركزها الرئيسي خاضعا للرقابة وفقا للقواعد التي يحددها مجلس إدارة الهيئة.
4 - الجهات الأخرى التي يقبل مجلس إدارة الشركة عضويتها وذلك وفقا للشروط والأوضاع التي تحددها اللائحة التنفيذية.$m224$,'d99f5dad5587709cee830c67ade4c03e'),
(20,0,$m224$المادة 20$m224$,$m224$يجب أن يتوافر لدى عضو الإيداع المركزي ـ وفقا للقواعد والمعايير التي تحددها اللائحة التنفيذية ـ ما يأتي:-
1 - الموارد المالية الكافية للوفاء بالتزاماته الناشئة عن العضوية ولمواجهة مخاطر المقاصة والتسوية في الأوراق المالية.
2 - العمالة والإمكانيات الفنية والدفاتر والسجلات والنظم والإجراءات اللازمة للتعامل مع نشاط الإيداع والقيد المركزي.
ويجوز لمن لا يتوافر لديه ذلك من الجهات المنصوص عليها في المادة (19) من هذا القانون أن يحصل على خدمات الإيداع المركزي من خلال أحد أعضائه.$m224$,'b729a2daa915bbb8029ed1aa2ce801d3'),
(21,0,$m224$المادة 21$m224$,$m224$تكون عضوية الإيداع المركزي متاحة للجهات المنصوص عليها في المادة (19) من هذا القانون والتي تتوافر فيها الشروط المنصوص عليها في المادة (20) منه، ويلتزم العضو بقواعد الإيداع المركزي وإجراءاته.
وعلى الشركة أن تراعي قواعد المساواة بين الأعضاء الذين تتماثل أوضاعهم، بما في ذلك ما يتصل بالأتعاب والمصاريف التي تتقاضاها والخدمات التي تقدمها.$m224$,'559be2af6501c1f31a00f91d42375a58'),
(22,0,$m224$المادة 22$m224$,$m224$على عضو الإيداع المركزي أن يبرم اتفاقا مكتوبا مع الشركة، وفقا للنموذج الذي تقره الهيئة، على أن يتضمن التزامه بما يأتي:
1 - مراعاة القواعد والنظم والإجراءات الخاصة بالإيداع والقيد المركزي، وما تدخله عليها الشركة من تعديلات بعد موافقة الهيئة.
2 - سداد الأتعاب والمصاريف نظير الخدمات التي تقدمها له الشركة وتعويضها عن إخلاله بالقواعد والنظم والإجراءات الخاصة بالإيداع والقيد المركزي.
3 - رهن الأوراق المالية التي أودعها لدى الشركة باسمه ولحسابه متى طلبت الشركة ذلك ضمانا لتنفيذ التزاماته والتصريح لها بالاقتراض بضمان رهن تلك الأوراق.
4 - تمكين من تندبه الشركة من الإطلاع على الدفاتر والسجلات الخاصة بالخدمات التي تقدمها الشركة إليه، والتحقق من سلامتها
5 - تنفيذ قرارات مجلس إدارة الشركة المتعلقة بالخدمات التي تقدمها.
6 - المشاركة في صندوق ضمان تسوية عمليات الأوراق المالية.
7 - المشاركة في تحمل خسائر الشركة طبقا للقواعد التي يضعها مجلس إدارتها وتعتمدها الهيئة.
ويجب أن يتضمن الاتفاق تحديدا لطريق الفصل فيما قد ينشأ بين طرفيه من منازعات.$m224$,'ea55d787d4b6926ab3e6fb3da50fd668'),
(23,0,$m224$المادة 23$m224$,$m224$مع عدم الإخلال بأحكام المادة (39) من هذا القانون، يضع مجلس إدارة الشركة القواعد الخاصة بالتدابير التي تتخذها بالنسبة لأعضاء الإيداع المركزي في حالات مخالفتهم لنظم العمل بالشركة، ولا تكون هذه القواعد نافذة إلا بعد اعتمادها من الهيئة.$m224$,'6953fb2185a9239b7ddd8b5adfcfa720'),
(24,0,$m224$المادة 24$m224$,$m224$على الشركة أن تراعي المساواة بين مصدري الأوراق المالية المتعاملين معها الذين تتماثل أوضاعهم، بما في ذلك ما يتعلق بالأتعاب والمصاريف التي تتقاضاها منهم وما تقدمه من خدمات القيد المركزي.$m224$,'ff4ebfd28528a17d4100f7185ddf7cde'),
(25,0,$m224$المادة 25$m224$,$m224$يحل قيد الأوراق المالية لدى الشركة محل سجلات المساهمين، أو سجلات ملكية الأوراق المالية لدى جهة الإصدار.
وعلى الشركة استحداث الوثائق التي تحل محل صكوك الأوراق المالية، وذلك في التعامل، وحضور الجمعيات العامة للمساهمين، وصرف الأرباح، والرهن، واستخدام حقوق الأولوية وغير ذلك وفقا للشروط والإجراءات المنصوص عليها في هذا القانون والقرارات الصادرة تنفيذا له.$m224$,'16789a5279cf15b9f6979fa76ea65e8e'),
(26,0,$m224$المادة 26$m224$,$m224$للشركة القيام بكل الأعمال الضرورية والملائمة لإتمام قيد الأوراق المالية وقيد نقل ملكيتها وما يتصل بذلك من البيانات، وعلى الأخص الحصول من الملاك المسجلين للأوراق المالية على أسماء ملاكها المستفيدين وحجم ملكية كل منهم.$m224$,'22134fbdb492b034f48393a8122bcb57'),
(27,0,$m224$المادة 27$m224$,$m224$يعد في الشركة سجل لقيد بيانات الملاك المستفيدين والتي تحصل عليها الشركة من الملاك المسجلين وفقا لأحكام المادة (26) من هذا القانون، ولا يجوز الإطلاع على هذا السجل لغير مصدري الأوراق المالية والجهات التي يصرح لها قانونا بذلك وفي حدود ما يخصها من بيانات السجل.$m224$,'7b684056090af46767a0d99e00273135'),
(28,0,$m224$المادة 28$m224$,$m224$على الملاك المسجلين الإفصاح عن بيانات الملاك المستفيدين إلى الشركة، وفقا للقواعد والإجراءات التي تحددها اللائحة التنفيذية.
فإذا كانت الملكية المسجلة لبنوك الإيداع، فإنها تلتزم بالاحتفاظ بسجل بالملاك المستفيدين، ويكون للشركة بناء على طلب مصدر الأوراق المالية، أن تطلع عليه.$m224$,'41307f8210164de916a7242e92bd0327'),
(29,0,$m224$المادة 29$m224$,$m224$تلتزم الشركة بإتمام قيد الأوراق المالية، وبالرد على استفسارات مصدريها وغيرهم من ذوي المصلحة خلال المدة ووفقا للأوضاع التي تحددها اللائحة التنفيذية.
وعلى الشركة أن تمسك الدفاتر والسجلات وتعد التقارير اللازمة لمباشرة نشاطها وفقا لما تحدده اللائحة التنفيذية.$m224$,'8800e836da0f657de38b49225cecdc5e'),
(30,0,$m224$المادة 30$m224$,$m224$لا يجوز لغير البنوك والجهات التي تحددها اللائحة التنفيذية أن تمارس نشاط أمناء الحفظ. ويصدر بالترخيص بممارسة هذا النشاط قرار من الهيئة وفقا للقواعد والإجراءات التي تحددها هذه اللائحة.
ويقصد بنشاط أمناء الحفظ كل نشاط يتناول حفظ الأوراق المالية والتعامل عليها، وإدارتها باسم ولصالح المالك أو باسم المالك المسجل لصالح المالك المستفيد، وذلك كله تنفيذا لتعليمات العميل وفي حدودها$m224$,'bb42d2fb750a295acd009a1df5a83d0b'),
(31,0,$m224$المادة 31$m224$,$m224$يلتزم المرخص له بممارسة نشاط أمناء الحفظ بما يأتي:
1 - الفصل بين الأوراق المالية والحسابات الخاصة به وبين ما يخص كل من عملائه، مع إمساك سجلات بذلك.
2 - إضافة وخصم المدفوعات الناتجة عن التعامل على الأوراق المالية وإدارتها في الحساب الخاص بكل عميل.
3 - رد الأوراق المالية للعميل وما له من مبالغ نقدية وذلك بناء على طلبه.$m224$,'b504f1a14211ad58db7a6fa3a5d06442'),
(32,0,$m224$المادة 32$m224$,$m224$على المرخص له بممارسة نشاط أمناء الحفظ أن يبرم اتفاقا مكتوبا مع كل من عملائه بما لا يتعارض مع القواعد والأحكام التي تضعها الهيئة.$m224$,'a1d3c94ed2d98f2d263853bfa6d4d2f9'),
(33,0,$m224$المادة 33$m224$,$m224$مع عدم الإخلال بالأحكام المنصوص عليها في هذا القانون، يكون تأسيس الشركة في شكل شركة مساهمة لمزاولة أوجه نشاطها وفقا للأحكام الخاصة بالشركات العاملة في مجال الأوراق المالية والمنصوص عليها في قانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992، ويكون نظامها الأساسي وفقا للنموذج المعد من الهيئة لهذا الغرض.
ويكون لجهات الإيداع المركزي الأجنبية أن تتمتع بصفة العضوية دون أن تلتزم بالمساهمة في الشركة، وذلك وفقا للأحكام التي تحددها اللائحة التنفيذية لهذا القانون.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'f97a85bf43a28922cfbd127086723314'),
(34,0,$m224$المادة 34$m224$,$m224$ملغاة.
*ألغيت بموجب قانون رقم 143 لسنة 2020.$m224$,'8e4cbae06576571d408855984a97425a'),
(35,0,$m224$المادة 35$m224$,$m224$على الشركة التي تطلب الترخيص لها بمزاولة نشاطي الإيداع والقيد المركزي في مصر أن ترفق بطلب الترخيص نسخة من القواعد والإجراءات الداخلية التي ستتبعها في مزاولة هذا النشاط بالإضافة إلى ما تطلبه الهيئة من مستندات وبيانات إضافية.
وعلى الهيئة عند إصدار قرارها في طلب الترخيص مراعاة احتياجات سوق رأس المال وما يحقق صالحه.
ويجوز أن يقتصر الترخيص على نوع أو أكثر من الأوراق المالية أو على نطاق جغرافي معين وأن يشتمل على أية شروط تتصل بمزاولة النشاط.$m224$,'e718474748327b712c5029f0067a412c'),
(35,1,$m224$المادة 35 مكرراً$m224$,$m224$للبنك المركزي المصري أن يباشر من خلال شركة مساهمة مملوكة له بالكامل أو بالمشاركة مع الغير، نشاطي الإيداع والقيد المركزي بالنسبة للأدوات والأوراق المالية الحكومية. ويتم تأسيس الشركة وفقا للأحكام الخاصة بالشركات العاملة في مجال الأوراق المالية المنصوص عليها في قانون سوق رأس المال المشار إليه، وذلك دون التقيد بالأحكام الواردة بهذا الفصل.
ويصدر مجلس إدارة الهيئة القواعد المنظمة لإيداع وقيد الأدوات والأوراق المالية الحكومية وتسوية المراكز المالية الناشئة عن تداولها بما في ذلك الحالات التي يتم فيها إنشاء صندوق لضمان الوفاء بالالتزامات الناشئة عن العمليات التي تقوم بها الشركة والقواعد المنظمة له، وذلك كله بعد أخذ رأي البنك المركزي المصري ووزارة المالية.
وتسري الأحكام المنصوص عليها في هذا القانون على عمليات الإيداع والقيد المركزي للأدوات والأوراق المالية الحكومية وعلى أعضاء الإيداع المركزي وأمناء الحفظ وذلك فيما لم يرد في شأنه نص خاصة في القواعد الصادرة وفقا لحكم الفقرة الثانية من هذه المادة.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'274218d77befa481dee0f34a0bbcd7fa'),
(35,2,$m224$المادة 35 مكرراً (1)$m224$,$m224$يكون تأسيس الشركات التي تقوم بإجراءات عمليات المقاصة والتسوية للعقود التي يجرى التعامل عليها في بورصات العقود الآجلة وفقا للأحكام الخاصة بالشركات العاملة في مجال الأوراق المالية والمنصوص عليها في قانون سوق رأس المال المشار إليه، على أن تكون في شكل شركة مساهمة، وترخص لها الهيئة بالقيام بتلك الأنشطة، ويكون نظامها الأساسي وفقا للنموذج المعد من الهيئة لهذا الغرض، وذلك دون التقيد بالأحكام الواردة بهذا الفصل.
وفي حالة التسوية المادية للعقود على السلع، يتم تسليم السلع محل العقود وفقا للقواعد التي تضعها وحدة الإشراف والرقابة على المخازن المعتمدة للسلع المشار إليها بالمادة (26 مكررا 6) من قانون سوق رأس المال.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'d6cd90079d41841930f768813cf4653a'),
(35,3,$m224$المادة 35 مكرراً (2)$m224$,$m224$تصدر الشركة المرخص لها بإجراء عمليات المقاصة والتسوية للعقود الآجلة لائحة بقواعد وإجراءات المقاصة والتسوية، ولا تكون هذه اللائحة نافذة إلا بعد اعتمادها من الهيئة.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'af0a35a957c9b8a8bf34da793faae083'),
(36,0,$m224$المادة 36$m224$,$m224$على الشركة أن تنشئ إدارة خاصة لكل من نشاط الإيداع المركزي ونشاط القيد المركزي ولصندوق ضمان التسوية، ويكون لكل إدارة حسابات مستقلة ومركز مالي خاص.$m224$,'34d59a0e6db97e6688afc8107d853fe5'),
(37,0,$m224$المادة 37$m224$,$m224$تكون أسهم شركة الإيداع والقيد المركزي للأوراق المالية مملوكة لبورصات الأوراق المالية المصرية ولأعضاء الإيداع المركزي، وتكون نسبة مساهمة عضو الإيداع المركزي على نحو يناسب حجم تعاملاته مع الشركة وفقا لما يسدده لها من أتعاب ومصروفات، وبشرط ألا تجاوز ملكية العضو أو أي مجموعة مرتبطة نسبة (5%) من رأسمال الشركة، ويحدد النظام الأساسي للشركة نسبة ما تمتلكه بورصات الأوراق المالية بشرط ألا تقل عن (5%) من رأسمال الشركة، وتمثل بعضو واحد على الأقل في مجلس إدارة الشركة. ويتم نقل ملكية الأسهم بين أعضاء الإيداع المركزي والبورصات بقرار من الجمعية العمومية غير العادية للشركة طبقا لنظامها الأساسي، ولا يجوز التصرف في هذه الأسهم إلا في حالة إعادة التوزيع، أو إذا زالت صفة العضوية في الإيداع المركزي.
ويتم نقل ملكية الأسهم في هذه الحالات إلى الشركة لتعيد توزيعها وفقا لما تحدده اللائحة التنفيذية لهذا القانون، ويقع باطلا كل تصرف يتم على خلاف ذلك.
وتحدد اللائحة التنفيذية لهذا القانون قواعد توزيع الحصص في رأسمال الشركة عند تأسيسها وعند قبول أعضاء جدد بها، والقواعد التي تنظم إعادة توزيع الأسهم فيما بين الأعضاء تنفيذا لأحكام الفقرة الأولى من هذه المادة، ويتم نقل ملكية الأسهم بين الأعضاء أو بينهم وبين الشركة وفقا لقيمتها الاسمية.
ويكون لجهات الإيداع المركزي الأجنبية أن تتمتع بصفة العضوية دون أن تلتزم بالمساهمة في الشركة، وذلك وفقا للأحكام التي تحددها اللائحة التنفيذية لهذا القانون.
ويقصد بالمجموعة المرتبطة كل مجموعة من الأعضاء تكون خاضعة للسيطرة الفعلية لنفس الأشخاص الطبيعيين أو لذات الأشخاص الاعتبارية، أو يجمع بينها اتفاق على التنسيق عند التصويت في اجتماعات الجمعية العامة للشركة أو في مجلس إدارتها.
ويحدد مجلس إدارة الهيئة شروط وضوابط وإجراءات الترخيص بمزاولة النشاط للشركات المنصوص عليها في هذا الفصل، والحد الأدنى لرأسمالها المصدر والمدفوع بالكامل بما لا يقل عن خمسين مليون جنيه، والحدود القصوى لمقابل الخدمات التي تقدمها.
ويصدر مجلس إدارة الهيئة قرارا بتحديد فئات رسوم الترخيص للشركات المشار إليها في الفقرة السابقة بما لا يجاوز مائة ألف جنيه، وتسدد الرسوم نقدا أو بإحدى وسائل الدفع غير النقدي المنصوص عليها بقانون تنظيم استخدام وسائل الدفع غير النقدي الصادر بالقانون رقم 18 لسنة 2019.
*معدلة بموجب قانون رقم 143 لسنة 2020.
*معدلة بموجب قانون رقم 127 لسنة 2009.$m224$,'ed76bf969b101850681b809f2a064452'),
(38,0,$m224$المادة 38$m224$,$m224$ويتم نقل ملكية الأسهم في هذه الحالات إلى الشركة لتعيد توزيعها وفقا لما تحدده اللائحة التنفيذية، ويقع باطلا كل تصرف يتم على خلاف ذلك.
*الفقرة الأولى ألغيت بموجب قانون رقم 143 لسنة 2020.$m224$,'6cb85e36b8c57ea66d99c798dd9e3089'),
(39,0,$m224$المادة 39$m224$,$m224$يفقد عضو الإيداع المركزي صفة العضوية في الحالات الآتية:
1 - إفلاس العضو أو زوال شخصيته القانونية.
2 - إلغاء ترخيص مزاولة العضو للنشاط المرخص له به من الهيئة.
3 - إلغاء العضوية بقرار من الهيئة بسبب مخالفة العضو لأحكام هذا القانون أو القرارات الصادرة تنفيذا له.
4 - إلغاء العضوية بقرار من الجمعية العامة غير العادية للشركة يصدر بأغلبية ثلاثة أرباع الأعضاء الحاضرين.$m224$,'c633806cae82998b12b6928e284edcd1'),
(40,0,$m224$المادة 40$m224$,$m224$ملغاة.
*ألغيت بموجب قانون رقم 143 لسنة 2020.$m224$,'8e4cbae06576571d408855984a97425a'),
(41,0,$m224$المادة 41$m224$,$m224$لمجلس إدارة الهيئة إلغاء الترخيص بمزاولة نشاطي الإيداع والقيد المركزي بسبب مخالفة الشركة لأحكام هذا القانون أو القرارات الصادرة تنفيذا له، إذا كان من شأن المخالفة إلحاق الضرر بسوق رأس المال أو تهديد استقراره، وذلك بعد إخطار الشركة بالمخالفة المنسوبة إليها وإعطائها مهلة مناسبة لتصحيح المخالفة أو إبداء دفاعها في شأنها.
ويجب أن يتضمن قرار إلغاء الترخيص الإجراءات والترتيبات اللازمة لمواجهة آثار الإلغاء ولا يكون القرار نافذا إلا بعد اعتماده من الوزير المختص.
وتحدد اللائحة التنفيذية القواعد والإجراءات التي تتبع في هذا الخصوص.$m224$,'1b5ecd9e4238cc5fd49df7aca71a8f30'),
(42,0,$m224$المادة 42$m224$,$m224$تقوم الهيئة بمراقبة الشركة والتفتيش على أعمالها وفقا للأحكام الخاصة بالشركات العاملة في مجال الأوراق المالية والمنصوص عليها في قانون سوق رأس المال المشار إليه.$m224$,'a2a77c192403ff4e603ec61306c3e9cf'),
(43,0,$m224$المادة 43$m224$,$m224$على الشركة القيام بما يأتي:
1 - الاستعانة بنظم وإجراءات ملائمة وكافية لحماية الأوراق المالية المحفوظة لديها.
2 - الاستعانة بمحاسبين قانونيين من خارج الشركة لتقييم أساليب المراجعة المالية لديها.
3 - إعداد تقارير دورية عن أداء الشركة يخطر بها أعضاء الإيداع المركزي ومصدرو الأوراق المالية.
4 - وضع ترتيبات لضمان حسن أداء نظام المعالجة الإلكتروني للمعلومات ونظام استرجاع المعلومات المحفوظة به في حال تعطله.$m224$,'d1664800ab43492a8c10b2174369c026'),
(44,0,$m224$المادة 44$m224$,$m224$تضع الشركة النظم الفنية لعمليات الإيداع والمقاصة والتسوية والقيد المركزي وغيرها من النظم المرتبطة بالتداول في سوق الأوراق المالية والرقابة عليها بعد موافقة مجلس إدارة الهيئة العامة للرقابة المالية.
*معدلة بموجب قانون رقم 127 لسنة 2009.$m224$,'ce22ca4ce583e3baa88dba3ba4851f8a'),
(45,0,$m224$المادة 45$m224$,$m224$يتولى مراجعة حسابات الشركة مراقبان للحسابات يتم اختيارهما من بين المقيدين في سجل تمسكه الهيئة لهذا الغرض.
وعلى الشركة أن تقدم للهيئة التقارير والقوائم المالية التي تلتزم بتقديمها الشركات التي تطرح أوراقا مالية في اكتتاب عام عملا بأحكام قانون سوق رأس المال المشار إليه، بالإضافة إلى التقارير الأخرى التي تحددها اللائحة التنفيذية.$m224$,'66c1c062161e24cce9e12a979f2c1ffe'),
(46,0,$m224$المادة 46$m224$,$m224$دون الإخلال بسلطة الجمعية العامة للشركة في اختيار أعضاء مجلس إدارتها تكون غالبية هؤلاء الأعضاء من ذوي الخبرة على أن يكون من بينهم كل من رئيس مجلس الإدارة والعضو المنتدب.
وتعرض قائمة المرشحين لرئاسة وعضوية مجلس إدارة الشركة بعد موافقة مجلس إدارة الهيئة العامة للرقابة المالية على الجمعية العامة للاختيار من بينها، كما يتم بموافقة مجلس إدارة هذه الهيئة تعيين المديرين التنفيذيين المسئولين عن المقاصة والتسوية والإيداع المركزي وصندوق ضمان التسوية.
*معدلة بموجب قانون رقم 127 لسنة 2009.$m224$,'e04bf6ec35513125451e6af41d8a972f'),
(47,0,$m224$المادة 47$m224$,$m224$لمجلس إدارة الهيئة حفاظا على استقرار سوق رأس المال وحسن سير أعمال الشركة أن يصدر قرارا مسببا باستبعاد عضو أو أكثر من أعضاء مجلس الإدارة، كما له تعيين عضو مراقب بمجلس إدارة الشركة وذلك للمدة التي يحددها مجلس إدارة الهيئة، ويكون لهذا العضو المشاركة في مناقشات المجلس وتسجيل رأيه فيما يتخذ من قرارات دون أن يكون له حق التصويت.$m224$,'0a1598372c1f8aa80827825cad08f7bb'),
(48,0,$m224$المادة 48$m224$,$m224$تكون الشركة مسئولة عن الضرر الناجم عن:
1 - عدم تسليم الأوراق المالية أو تحويل الأموال التي تخص العضو أو أي من عملائه أو عدم قيد أو نقل ملكية الأوراق المالية.
2 - فقد الأوراق المالية أو الأموال.
3 - أي ضرر آخر يلحق بالعضو أو بأي من عملائه أو بمصدري الأوراق المالية أو بالغير والذي تكون الشركة مسئولة عنه وفقا لنظامها الأساسي أو للإجراءات والقواعد المتبعة لديها أو للاتفاق الذي ينظم علاقتها مع العضو أو مع مصدر الأوراق المالية.
ويتحمل الأعضاء جبر الضرر الناجم عن مسئولية الشركة وفقا للقواعد التي تضعها بشأن المشاركة في تحمل تلك المسئولية، وذلك ما لم يكن الضرر مؤمنا عليه.$m224$,'7d0b1b7e5472d723f72aad054796eca8'),
(49,0,$m224$المادة 49$m224$,$m224$يجب أن تتوافر لدى الشركة الوسائل والإجراءات الكفيلة بالحفاظ على سرية المعلومات التي تخص المعاملات التي تتم من خلالها، وبضمان عدم قيام أي من مديريها أو العاملين بها أو وكلائها بإفشاء تلك المعلومات، كما يلزم أن يكون لدى الشركة وسائل ملائمة لكشف من يخالف تلك الإجراءات والقواعد.
ويجوز لعضو الإيداع المركزي ولمصدر الأوراق المالية أن يطلب الاطلاع على دفاتر الشركة وسجلاتها التي تتعلق بمعاملاته معها، وعلى الشركة أن تمكنه هو أو من يعينه من الاطلاع على تلك الدفاتر والسجلات في مقرها ومن الحصول على صورة منها.$m224$,'3df0b7bf1796f230605cb4ddeb97f328'),
(50,0,$m224$المادة 50$m224$,$m224$يضع مجلس إدارة الهيئة القواعد الخاصة بالتدابير التي تتخذها بالنسبة إلى الشركة في حالات مخالفة أحكام هذا القانون والقرارات الصادرة تنفيذا له، ولا تكون هذه القرارات نافذة إلا بعد اعتمادها من الوزير المختص.$m224$,'e1d33fdc29de73a7182079676e0f36c6'),
(51,0,$m224$المادة 51$m224$,$m224$تسري أحكام قانون سوق رأس المال المشار إليه بشأن من لهم صفة الضبطية القضائية وسلطاتهم في إثبات الجرائم التي تقع بالمخالفة لأحكام هذا القانون والقرارات الصادرة تنفيذا له.$m224$,'360204029964ee1117accd5fe9fe7595'),
(51,1,$m224$المادة 51 مكرراً$m224$,$m224$مع مراعاة أحكام قانون التجارة الصادر بالقانون رقم 17 لسنة 1999، تسري الأحكام الواردة في هذا الفصل على رهن الأوراق والأدوات المالية والأوراق والأدوات المالية الحكومية.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'25f1bb454ed80d55fcf96be97a4ab24b'),
(51,2,$m224$المادة 51 مكرراً (1)$m224$,$m224$يكون اتفاق رهن الأوراق أو الأدوات المالية وفقا لأحكام هذا القانون ملزما ونافذا في مواجهة الغير متى كان مكتوبا وثابت التاريخ ومتضمنا تحديد محل الرهن، ويكفي لتحديد الرهن أن يتم قيده في حساب الراهن لدى الشركة.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'208d181d02865ca184caeee8a6c5e4d3'),
(51,3,$m224$المادة 51 مكرراً (2)$m224$,$m224$للمدين الراهن للأوراق أو الأدوات المالية الحق في استغلالها متى كان اتفاق الرهن ينص على ذلك وبشرط أن يلتزم باستبدالها بأوراق أو أدوات مالية أخرى لا تقل في القيمة أو الشروط عن الأوراق أو الأدوات المرهونة قبل حلول أجل الالتزام المضمون بالرهن، ولا يخل ذلك بكافة حقوق الدائن المرتهن على الأوراق أو الأدوات المالية وفقا لاتفاق الرهن بما في ذلك الحق في التنفيذ على الأوراق أو الأدوات المرهونة أو تلك التي تم استبدالها بها.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'a60dc695be2f1fb9269ea201fdaf4036'),
(51,4,$m224$المادة 51 مكرراً (3)$m224$,$m224$يكون للدائن المرتهن للأوراق أو الأدوات المالية عند تحقق الواقعة المنشئة لحقه في التنفيذ، وبعد مضي خمسة أيام من تكليف المدين بالوفاء بموجب كتاب مسجل مصحوب بعلم الوصول، أن يباشر ذلك عن طريق بيعها أو الاستحواذ عليها مع خصم قيمتها من مستحقاته المالية.
ومع ذلك لا يجوز الاستحواذ مباشرة على الأوراق أو الأدوات المالية إلا إذا نص اتفاق الرهن على ذلك وعلى أسلوب تقييم الأوراق أو الأدوات المالية بغرض التنفيذ.
وفي جميع الأحوال، لا يجوز الاتفاق على إرجاء التنفيذ على الأوراق أو الأدوات المالية المرهونة لحين صدور قرار إداري أو حكم قضائي أو إجراء مزاد أو لحين انقضاء فترة زمنية معينة، كما لا يترتب على إفلاس المدين الراهن أو الدائن المرتهن أو إعادة هيكلته إرجاء التنفيذ.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'5ea725116f4873c7902cf82197f31e9a'),
(51,5,$m224$المادة 51 مكرراً (4)$m224$,$m224$يكون اتفاق رهن الأوراق أو الأدوات المالية وما يرتبط به من رهون إضافية أو استبدال لمحل الرهن ساريا ونافذا تجاه الكافة متى انعقد قبل بدء إجراءات تصفية أو إعادة هيكلة المدين الراهن أو يوم بدء تلك الإجراءات بشرط إثبات المدين الراهن عدم علمه بها.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'a68f9ebad223b02f98fe4e08653f9495'),
(52,0,$m224$المادة 52$m224$,$m224$تكون جميع القيود والعمليات التي تمت وأصبحت نهائية وفقا للقواعد المعتمدة من مجلس إدارة الهيئة سارية، ولا يجوز وقفها أو إبطالها أو الحجز عليها وذلك دون التقيد بالأحكام المنصوص عليها في أي قانون آخر.
وفي حالة إفلاس أحد أعضاء الإيداع المركزي تقوم الشركة بإتمام المقاصة والتسوية للعمليات التي كان طرفا فيها والمراكز المالية الناشئة عن الأوامر النهائية الصادرة منه قبل إخطار الشركة بحكم شهر إفلاسه، وتكون تلك العمليات والأوامر نافذة في مواجهة الكافة.
ومع عدم الإخلال بنهائية العملية، يجوز للهيئة من تلقاء نفسها أو بناء على طلب أمين التفليسة أو أحد ذوي المصلحة، أن تعكس قيد تلك العمليات إذا تبين لها أنها تمت بناء على غش أو تدليس أو نتيجة لخطأ أو إهمال أو سوء نية من الشركة أو من أحد أعضاء الإيداع المركزي.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'037843b0886c16c5a81b2ee9e16b8c4d'),
(53,0,$m224$المادة 53$m224$,$m224$تسري أحكام المادتين (50) و(51) من قانون سوق رأس المال المشار إليه على التظلمات التي يقدمها أصحاب الشأن من القرارات التي تصدر من الوزير المختص أو من الهيئة تطبيقا لأحكام هذا القانون والقرارات الصادرة تنفيذا له.$m224$,'b88ddf206e3686f053092e6ab1a1bc8b'),
(54,0,$m224$المادة 54$m224$,$m224$مع عدم الإخلال بأية عقوبة أشد منصوص عليها في أي قانون آخر، يعاقب بالحبس مدة لا تقل عن سنة وبغرامة لا تقل عن مائة ألف جنيه ولا تزيد على مائتي ألف جنيه أو بإحدى هاتين العقوبتين كل من باشر نشاطا من الأنشطة الخاضعة لأحكام هذا القانون دون أن يكون مرخصا له في ذلك.$m224$,'ee5d90d512e8d6e14649271bac3290e7'),
(55,0,$m224$المادة 55$m224$,$m224$مع عدم الإخلال بأي عقوبة أشد منصوص عليها في أي قانون آخر، يعاقب بغرامة لا تقل عن خمسين ألف جنيه ولا تزيد على مائة ألف جنيه كل من خالف أحكام الفقرة الثالثة من المادة (8) والمواد (10, 28, 31, 43, 46) من هذا القانون.
ويجوز أن تتضمن القرارات الصادرة عن مجلس إدارة الهيئة تطبيقا لأحكام هذا القانون تقرير عقوبة الغرامة لكل من يخالفها، على أن ينشر القرار في الوقائع المصرية وألا تقل الغرامة عن عشرة آلاف جنيه ولا تزيد على خمسين ألف جنيه.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'68f7e3b5335ffa5a54f62d920c111386'),
(56,0,$m224$المادة 56$m224$,$m224$مع عدم الإخلال بأية عقوبة أشد منصوص عليها في أي قانون آخر، يعاقب بالحبس مدة لا تقل عن ستة أشهر وبغرامة لا تقل عن خمسين ألف جنيه ولا تزيد على مائة ألف جنيه أو بإحدى هاتين العقوبتين كل من أفشى سرا اتصل به بحكم عمله تطبيقا لأحكام هذا القانون أو حقق نفعا منه بطريق مباشر أو غير مباشر.$m224$,'29f483c4302c4260a98d9a145023d8fa'),
(57,0,$m224$المادة 57$m224$,$m224$يجوز فضلا عن العقوبات المقررة للجرائم المنصوص عليها في المواد السابقة الحكم بالحرمان من مزاولة المهنة أو بحظر مزاولة النشاط الذي وقعت الجريمة بمناسبته، وذلك لمدة لا تزيد على ثلاث سنوات، ويكون الحكم بذلك وجوبيا في حالة العود.$m224$,'d9f5bcafff1331783655eccf34194f1d'),
(58,0,$m224$المادة 58$m224$,$m224$يعاقب المسئول عن الإدارة الفعلية بالشركة المخالفة بذات العقوبات المقررة عن الأفعال التي ترتكب بالمخالفة لأحكام هذا القانون إذا ثبت علمه بها وكان إخلاله بالواجبات التي تفرضها عليه تلك الإدارة قد أسهم في وقوع الجريمة.
وتكون الشركة مسئولة بالتضامن عن الوفاء بما يحكم به من عقوبات مالية إذا كانت المخالفة قد ارتكبت من أحد العاملين بالشركة باسمها أو لصالحها.$m224$,'9c53a5706254e618572602ca233b0a86'),
(59,0,$m224$المادة 59$m224$,$m224$لا ترفع الدعوى الجنائية بالنسبة للجرائم المنصوص عليها في هذا القانون إلا بناء على طلب كتابي من الوزير المختص بعد أخذ رأي رئيس الهيئة.
ويجوز للوزير المختص التصالح مع المتهم أو المحكوم عليه في أي من تلك الجرائم مقابل أداء مبلغ للهيئة لا يقل عن الحد الأقصى للغرامة ولا يجاوز ضعفه بالإضافة إلى قيمة ما عاد على المتهم من نفع أو ما سببه من ضرر بسبب الجريمة أيهما أكبر، ويترتب على التصالح انقضاء الدعوى الجنائية.
وتأمر النيابة العامة بوقف تنفيذ عقوبة الحبس إذا تم الصلح أثناء تنفيذها ولو بعد صيرورة الحكم باتًا$m224$,'ce4b15a1ce5ddb5ddadc8cbaddd2b6a3');

INSERT INTO m224_ver VALUES
(1,-1,1,$m224$يعمل بأحكام القانون المرافق في شأن الإيداع والقيد المركزي والتسوية والمقاصة في الأوراق المالية. ويلغى كل حكم يخالف أحكامه.$m224$,'d450eac25de86c7a8f33d202fded5849',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(2,-1,1,$m224$في تطبيق أحكام القانون المرافق ولائحته التنفيذية والقرارات المنفذة له يقصد بـ الوزير المختص رئيس مجلس الوزراء وبـالهيئة الهيئة العامة للرقابة المالية.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'86cb7c775abf4175fee08da58f5ce0cd',DATE '2020-07-10',NULL,'active',143,2020,$m224$عُدّلت بالقانون رقم 143 لسنة 2020 (النص الوارد هو النص بعد التعديل؛ النص الأصلى قبل التعديل غير وارد فى المصدر). تاريخ نفاذ التعديل مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(3,-1,1,$m224$يصدر رئيس مجلس الوزراء بناء على عرض رئيس مجلس إدارة الهيئة العامة للرقابة المالية وبعد أخذ رأي مجلس الإدارة، اللائحة التنفيذية للقانون المرافق خلال مدة لا تجاوز أربعة أشهر من تاريخ العمل به.
وإلى أن تصدر اللائحة التنفيذية والقرارات المنفذة للقانون المرافق، يستمر العمل بالأحكام والقواعد والنظم القائمة في تاريخ العمل به فيما لا يتعارض مع أحكامه.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'56e3b5c17b936d60a4d09174e108a4fb',DATE '2020-07-10',NULL,'active',143,2020,$m224$عُدّلت بالقانون رقم 143 لسنة 2020 (النص الوارد هو النص بعد التعديل؛ النص الأصلى قبل التعديل غير وارد فى المصدر). تاريخ نفاذ التعديل مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(4,-1,1,$m224$على الشركات القائمة في تاريخ العمل بهذا القانون والتي تزاول نشاط الإيداع أو القيد المركزي أو المقاصة أو التسوية في الأوراق المالية أو نشاط أمناء الحفظ أن توفق أوضاعها وفقا لأحكامه خلال ستة أشهر من ذلك التاريخ.
وعلى الشركات التي أصدرت أوراقا مالية قبل تاريخ العمل بهذا القانون الالتزام بأحكام القانون المرافق خلال مدة لا تجاوز سنة من ذات التاريخ.$m224$,'3ff7d7f84aac4281662508a30d4a3165',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(5,-1,1,$m224$يصدر رئيس مجلس الوزراء قرارا بالمراحل والمواعيد التي يتم خلالها إيداع وإلغاء صكوك الأوراق المالية التي يتعين إيداعها وقيدها طبقا لأحكام القانون المرافق لدى شركة الإيداع والقيد المركزي، وعلى الشركة اتخاذ التدابير المناسبة للالتزام بتلك المواعيد.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'49f1a2639e046826b2a5622b77d6059f',DATE '2020-07-10',NULL,'active',143,2020,$m224$عُدّلت بالقانون رقم 143 لسنة 2020 (النص الوارد هو النص بعد التعديل؛ النص الأصلى قبل التعديل غير وارد فى المصدر). تاريخ نفاذ التعديل مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(6,-1,1,$m224$تسري أحكام قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981 وقانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992 فيما لم يرد به نص خاص في القانون المرافق.$m224$,'dddf125bba5778dbe89ce9532436e638',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(7,-1,1,$m224$ينشر هذا القانون في الجريدة الرسمية، ويعمل به من أول الشهر التالي لمضي شهر على تاريخ نشره. يبصم هذا القانون بخاتم الدولة، وينفذ كقانون من قوانينها.$m224$,'29abe84fc242432dc44b69addc19d31e',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(1,0,1,$m224$يقصد بالشركة كل شركة مرخص لها بمزاولة نشاطي الإيداع والقيد المركزي للأوراق والأدوات المالية، كما يقصد بأعضاء الإيداع المركزي الجهات المنصوص عليها في المادة (19) من هذا القانون.
وفيما لم يرد في شأنه نص خاص في هذا القانون، تسري جميع الأحكام المتعلقة بالأوراق المالية وشركات الإيداع والقيد المركزي لها والواردة في هذا القانون على كل ما يتعلق بالعقود الآجلة والأوراق والأدوات المالية الحكومية وشركات الإيداع والقيد المركزي لها، وذلك فيما لا يتعارض مع طبيعة أي منها.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'3e5ff9cdf02f81682eba016876e8f1bc',DATE '2020-07-10',NULL,'active',143,2020,$m224$عُدّلت بالقانون رقم 143 لسنة 2020 (النص الوارد هو النص بعد التعديل؛ النص الأصلى قبل التعديل غير وارد فى المصدر). تاريخ نفاذ التعديل مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(2,0,1,$m224$يقصد بنشاط الإيداع المركزي كل نشاط يتناول إيداع وحفظ الأوراق المالية وإجراء المقاصة وتسوية المراكز المالية الناشئة عن عمليات التداول ونقل ملكية الأوراق المالية عن طريق القيد الدفتري، بما في ذلك:
1 - حفظ الأوراق المالية لدى الشركة أو لدى إحدى الجهات المرخص لها بذلك.
2 - نقل ملكية الأوراق المالية التي تم التعامل عليها عن طريق أعضاء الإيداع المركزي وذلك بالقيد الدفتري.
3 - قيد حقوق الرهن على الأوراق المالية.
4 - جراء المقاصة وتسوية المراكز المالية الناشئة عن تداول الأوراق المالية.
5 - حفظ وتسوية الأوراق والأدوات المالية الحكومية وفقا للقواعد التي يضعها مجلس إدارة الهيئة، بعد أخذ رأي البنك المركزي المصري ووزارة المالية.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'ceaf395c2e8be70f628f56412a59b8a9',DATE '2020-07-10',NULL,'active',143,2020,$m224$عُدّلت بالقانون رقم 143 لسنة 2020 (النص الوارد هو النص بعد التعديل؛ النص الأصلى قبل التعديل غير وارد فى المصدر). تاريخ نفاذ التعديل مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(3,0,1,$m224$يقصد بنشاط القيد المركزي كل نشاط يتناول إمساك سجلات بملكية الأوراق المالية وحقوق الرهن المقيدة عليها، بما في ذلك:
1 - إمساك السجلات بأسماء ملاك الأسهم وغيرها من الأوراق المالية وما يرد عليها من حقوق وتصرفات.
2 - توزيع المستحقات الناتجة عن الأوراق المالية التي يتم حفظها لدى الشركة، بما في ذلك الأصل والعائد وتوزيعات الأرباح وقيم الاسترداد ومدفوعات إعادة الهيكلة.
3 - نشر التقارير والمعلومات التي تفصح عنها الجهات التي تصدر الأوراق المالية أو المتعلقة بتلك الأوراق
4 - تقديم الخدمات المتصلة بإصدار الأوراق المالية بالنيابة عن المصدر.
5 - جراء ما يلزم لاستبدال الأوراق المالية عند إعادة هيكلة الجهة المصدرة.$m224$,'350c52e0b27b5c39fb8f0f9f3c049caf',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(4,0,1,$m224$لا تنتقل ملكية الأوراق المالية التي تم إيداعها لدى الشركة إلا بإتمام تسوية العمليات التي أجريت عليها.$m224$,'f040a16e3023dbc02eaa6e78cd1c6da3',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(5,0,1,$m224$لمالك الورقة المالية جميع الحقوق التي تنتجها ملكيته لها، ويتم إيداع وقيد الورقة باسمه.
ومع ذلك يجوز أن تودع الأوراق وتقيد باسم شخص، ويكون لشخص آخر أو أكثر الحقوق التي تنتجها، ويطلق على الأول اسم المالك المسجل وعلى الثاني اسم المالك المستفيد وفي هذه الحالة يلتزم المالك المسجل بالتزامات أمناء الحفظ المنصوص عليها في هذا القانون.$m224$,'b0d37235bf32e352c877a171de492cc6',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(6,0,1,$m224$لا يجوز أن يكون مالكا مسجلا إلا بنوك الإيداع والجهات التي تمارس أنشطة أمناء الحفظ أو إدارة محافظ الأوراق المالية أو أي نشاط آخر يصدر به قرار من الوزير المختص بعد أخذ رأي الهيئة.
ويقصد ببنوك الإيداع البنوك التي تصدر شهادات إيداع يتم قيدها وتداولها في بورصات الأوراق المالية المحلية أو الدولية في مقابل ملكيتها ملكية مسجلة لأوراق مالية.
وعلى كل مالك مسجل أن يقيد اسمه وبياناته في سجل تعده الهيئة لهذا الغرض، ويحدد مجلس إدارة الهيئة قواعد وإجراءات القيد فيه.$m224$,'90f6774a7baeed6eb1de306fcb699fa6',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(7,0,1,$m224$يكون تعامل مصدر الورقة المالية مع المالك المسجل، ويكون تعامله على هذا النحو مبرئا لذمته. ويلتزم المالك المسجل بأن يمكن المالك المستفيد من جميع الحقوق التي تنتجها الورقة بما في ذلك الحصول على الحقوق المالية التي تستحق عنها والمعلومات المتعلقة بها التي يفصح عنها مصدر الورقة، كما يلتزم بتعليمات المالك المستفيد بالنسبة إلى التصويت عن الورقة والتصرف فيها، وتؤول حصيلة التصرف إلى المالك المستفيد.
وفي جميع حالات انقضاء شخصية المالك المسجل أو إفلاسه، ينتقل تسجيل الأوراق المالية إلى المالك المستفيد.$m224$,'99bab706024140e85bb2210320907912',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(8,0,1,$m224$تتماثل الأوراق المالية التي تم إيداعها لدى الشركة والمزايا التي تنتجها وتحل محل بعضها إذا كانت من ذات النوع والإصدار والعملة، ولا يكون لأي عضو من أعضاء الإيداع المركزي التمسك بحق أو التزام على أوراق بذاتها.
وتسري أحكام الفقرة السابقة بالنسبة إلى الملاك المستفيدين لأوراق مالية لها مالك مسجل واحد. ويلتزم المالك المسجل بالتصويت عن كل مالك من الملاك المستفيدين وفقا للتعليمات التي تلقاها منه.$m224$,'fc0e3e00230f640dc7b4bf1775d6c466',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(9,0,1,$m224$للشركة أن تباشر نشاطها بالنسبة للأوراق المالية بما في ذلك الأوراق المالية الأجنبية، والتي يشترط فيها أن تكون مقيدة في بورصة الأوراق المالية بالدولة التي صدرت بها.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'ef0de3955c218ba0cfa1df93bd8f04a9',DATE '2020-07-10',NULL,'active',143,2020,$m224$عُدّلت بالقانون رقم 143 لسنة 2020 (النص الوارد هو النص بعد التعديل؛ النص الأصلى قبل التعديل غير وارد فى المصدر). تاريخ نفاذ التعديل مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(10,0,1,$m224$لا يجوز لممثلي أعضاء مجلس إدارة الشركة والعاملين بها وأزواجهم وأولادهم القصر التعامل في الأوراق المالية، إلا بعد موافقة مجلس إدارة الشركة. ويصدر بتحديد قواعد وإجراءات الموافقة قرار من الهيئة وفقا للقواعد التي تحددها اللائحة التنفيذية.$m224$,'26380cd53b93a76e16657cb7b33e225e',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(11,0,1,$m224$يجب أن تودع لدى الشركة الأوراق المالية المقيدة في إحدى بورصات الأوراق المالية وجميع الأوراق المالية التي تصدرها أي شركة إذا طرحت أوراقا مالية لها في اكتتاب عام. ويجوز إيداع غير ذلك من الأوراق المالية.
وفي جميع هذه الحالات يكون قيد الأوراق المودعة وإجراء المقاصة والتسوية للعمليات التي تتم عليها من خلال الشركة.$m224$,'f019f8097d4026abe40c766fcde3028d',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(12,0,1,$m224$يمتنع التعامل على الأوراق المالية المودعة أو اقتضاء الحقوق المترتبة عليها إلا عن طريق القيد الدفتري لدى الشركة. ولا يجوز سحب الأوراق المالية بعد إيداعها إلا في الحالات التي يصدر بها قرار من رئيس مجلس إدارة الهيئة.$m224$,'0052c456709043b05582b741ab902154',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(13,0,1,$m224$عند إلغاء صكوك الأوراق المالية وفقا للقواعد التي يحددها قرار من الوزير المختص يحل محلها صك واحد عن كل إصدار للأوراق يودع لدى الشركة، على أن يدون فيه عددها ونوعها وقيمتها وغير ذلك من البيانات التي تحددها اللائحة التنفيذية.$m224$,'9b9656458b067bb7112aceed89b527dd',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(14,0,1,$m224$تقوم الشركة بإجراء عمليات المقاصة في الأوراق المالية لحساب أعضاء الإيداع المركزي وذلك بهدف تحديد صافي حقوق والتزامات كل منهم، كما تقوم الشركة بإجراء عمليات تسوية المراكز المالية الناشئة عن تداول الأوراق المالية.
وتبين اللائحة التنفيذية ما تشمله المقاصة والتسوية من عمليات وماتتطلبه من إجراءات.$m224$,'73a75dcca82b56a93e9031700d58e84f',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(15,0,1,$m224$تجرى الشركة عمليات المقاصة والتسوية في الأوراق المالية على أساس التسليم مقابل سداد الثمن، ويجب ألا تتجاوز الفترة بين إجراء عملية التداول وإتمام التسوية الخاصة بها المدة التي يصدر بتحديدها قرار من مجلس إدارة الهيئة.$m224$,'0e6f110e2190684d5ba583b512089a05',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(16,0,1,$m224$على مجلس إدارة الشركة أن يصدر بعد موافقة الهيئة قرارا بالنظم اللازمة لضمان تنفيذ أعضاء الإيداع المركزي لالتزاماتهم المتعلقة بالتسوية في الأوراق المالية، وله أن يلجأ في ذلك إلى كل أو بعض الوسائل الآتية:
1 - اشتراط قيام العضو بتقديم كفالة من الغير.
2 - تعيين حد أقصى لالتزامات العضو النقدية عن معاملاته مع الشركة أو من خلالها.
3 - تحديد قواعد وإجراءات تصفية العمليات التي لا تتم تسويتها.
4 - وضع نظام لتسليف الأوراق المالية بين أعضاء الإيداع المركزي.$m224$,'722be3801d71c2d50a43f837ff5c92a6',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(17,0,1,$m224$على الشركة أن تقوم بحفظ الأوراق المالية لديها أو لدى إحدى الجهات المرخص لها بممارسة نشاط أمناء الحفظ، وأن تودع الأموال الخاصة بأعضاء الإيداع المركزي لدى أحد البنوك الخاضعة لإشراف البنك المركزي المصري.$m224$,'9b5e3b5595931891f0807f436fb03191',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(18,0,1,$m224$على الشركة أن تنشئ وتدير صندوقا لضمان الوفاء بالالتزامات الناشئة عن عمليات الأوراق المالية يلتزم الأعضاء بالاشتراك فيه، ويصدر بنظامه وبقواعد الاشتراك فيه وبمقابل التأخير عن الوفاء بالاشتراك في ميعاد استحقاقه، قرار من مجلس إدارة الهيئة بناء على عرض مجلس إدارة الشركة.
ويعاقب بغرامة قدرها (1%) من قيمة المبالغ موضوع الالتزامات المتأخرة والناشئة عن عمليات الأوراق المالية، وذلك عن كل يوم من أيام التأخير في الوفاء بهذه الالتزامات.
*معدلة بموجب قانون رقم 143 لسنة 2004.$m224$,'e9fb86a0e89702831f05681a6d2c2c27',DATE '2000-07-01',NULL,'active',143,2004,$m224$عُدّلت بالقانون رقم 143 لسنة 2004 (النص الوارد هو النص بعد التعديل). تاريخ نفاذ التعديل غير وارد فى المصدر فسُجل تاريخ نفاذ القانون الأصلى.$m224$),
(19,0,1,$m224$يجب أن يكون أعضاء الإيداع المركزي من بين الجهات الآتية:
1 - البنوك وفروع البنوك المسجلة لدى البنك المركزي المصري.
2 - الشركات العاملة في مجال الأوراق المالية وفقا للأنشطة التي يحددها مجلس إدارة الهيئة.
3 - الشركات والجهات الأجنبية التي تمارس نشاط الإيداع المركزي للأوراق المالية، بشرط أن يكون مركزها الرئيسي خاضعا للرقابة وفقا للقواعد التي يحددها مجلس إدارة الهيئة.
4 - الجهات الأخرى التي يقبل مجلس إدارة الشركة عضويتها وذلك وفقا للشروط والأوضاع التي تحددها اللائحة التنفيذية.$m224$,'d99f5dad5587709cee830c67ade4c03e',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(20,0,1,$m224$يجب أن يتوافر لدى عضو الإيداع المركزي ـ وفقا للقواعد والمعايير التي تحددها اللائحة التنفيذية ـ ما يأتي:-
1 - الموارد المالية الكافية للوفاء بالتزاماته الناشئة عن العضوية ولمواجهة مخاطر المقاصة والتسوية في الأوراق المالية.
2 - العمالة والإمكانيات الفنية والدفاتر والسجلات والنظم والإجراءات اللازمة للتعامل مع نشاط الإيداع والقيد المركزي.
ويجوز لمن لا يتوافر لديه ذلك من الجهات المنصوص عليها في المادة (19) من هذا القانون أن يحصل على خدمات الإيداع المركزي من خلال أحد أعضائه.$m224$,'b729a2daa915bbb8029ed1aa2ce801d3',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(21,0,1,$m224$تكون عضوية الإيداع المركزي متاحة للجهات المنصوص عليها في المادة (19) من هذا القانون والتي تتوافر فيها الشروط المنصوص عليها في المادة (20) منه، ويلتزم العضو بقواعد الإيداع المركزي وإجراءاته.
وعلى الشركة أن تراعي قواعد المساواة بين الأعضاء الذين تتماثل أوضاعهم، بما في ذلك ما يتصل بالأتعاب والمصاريف التي تتقاضاها والخدمات التي تقدمها.$m224$,'559be2af6501c1f31a00f91d42375a58',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(22,0,1,$m224$على عضو الإيداع المركزي أن يبرم اتفاقا مكتوبا مع الشركة، وفقا للنموذج الذي تقره الهيئة، على أن يتضمن التزامه بما يأتي:
1 - مراعاة القواعد والنظم والإجراءات الخاصة بالإيداع والقيد المركزي، وما تدخله عليها الشركة من تعديلات بعد موافقة الهيئة.
2 - سداد الأتعاب والمصاريف نظير الخدمات التي تقدمها له الشركة وتعويضها عن إخلاله بالقواعد والنظم والإجراءات الخاصة بالإيداع والقيد المركزي.
3 - رهن الأوراق المالية التي أودعها لدى الشركة باسمه ولحسابه متى طلبت الشركة ذلك ضمانا لتنفيذ التزاماته والتصريح لها بالاقتراض بضمان رهن تلك الأوراق.
4 - تمكين من تندبه الشركة من الإطلاع على الدفاتر والسجلات الخاصة بالخدمات التي تقدمها الشركة إليه، والتحقق من سلامتها
5 - تنفيذ قرارات مجلس إدارة الشركة المتعلقة بالخدمات التي تقدمها.
6 - المشاركة في صندوق ضمان تسوية عمليات الأوراق المالية.
7 - المشاركة في تحمل خسائر الشركة طبقا للقواعد التي يضعها مجلس إدارتها وتعتمدها الهيئة.
ويجب أن يتضمن الاتفاق تحديدا لطريق الفصل فيما قد ينشأ بين طرفيه من منازعات.$m224$,'ea55d787d4b6926ab3e6fb3da50fd668',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(23,0,1,$m224$مع عدم الإخلال بأحكام المادة (39) من هذا القانون، يضع مجلس إدارة الشركة القواعد الخاصة بالتدابير التي تتخذها بالنسبة لأعضاء الإيداع المركزي في حالات مخالفتهم لنظم العمل بالشركة، ولا تكون هذه القواعد نافذة إلا بعد اعتمادها من الهيئة.$m224$,'6953fb2185a9239b7ddd8b5adfcfa720',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(24,0,1,$m224$على الشركة أن تراعي المساواة بين مصدري الأوراق المالية المتعاملين معها الذين تتماثل أوضاعهم، بما في ذلك ما يتعلق بالأتعاب والمصاريف التي تتقاضاها منهم وما تقدمه من خدمات القيد المركزي.$m224$,'ff4ebfd28528a17d4100f7185ddf7cde',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(25,0,1,$m224$يحل قيد الأوراق المالية لدى الشركة محل سجلات المساهمين، أو سجلات ملكية الأوراق المالية لدى جهة الإصدار.
وعلى الشركة استحداث الوثائق التي تحل محل صكوك الأوراق المالية، وذلك في التعامل، وحضور الجمعيات العامة للمساهمين، وصرف الأرباح، والرهن، واستخدام حقوق الأولوية وغير ذلك وفقا للشروط والإجراءات المنصوص عليها في هذا القانون والقرارات الصادرة تنفيذا له.$m224$,'16789a5279cf15b9f6979fa76ea65e8e',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(26,0,1,$m224$للشركة القيام بكل الأعمال الضرورية والملائمة لإتمام قيد الأوراق المالية وقيد نقل ملكيتها وما يتصل بذلك من البيانات، وعلى الأخص الحصول من الملاك المسجلين للأوراق المالية على أسماء ملاكها المستفيدين وحجم ملكية كل منهم.$m224$,'22134fbdb492b034f48393a8122bcb57',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(27,0,1,$m224$يعد في الشركة سجل لقيد بيانات الملاك المستفيدين والتي تحصل عليها الشركة من الملاك المسجلين وفقا لأحكام المادة (26) من هذا القانون، ولا يجوز الإطلاع على هذا السجل لغير مصدري الأوراق المالية والجهات التي يصرح لها قانونا بذلك وفي حدود ما يخصها من بيانات السجل.$m224$,'7b684056090af46767a0d99e00273135',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(28,0,1,$m224$على الملاك المسجلين الإفصاح عن بيانات الملاك المستفيدين إلى الشركة، وفقا للقواعد والإجراءات التي تحددها اللائحة التنفيذية.
فإذا كانت الملكية المسجلة لبنوك الإيداع، فإنها تلتزم بالاحتفاظ بسجل بالملاك المستفيدين، ويكون للشركة بناء على طلب مصدر الأوراق المالية، أن تطلع عليه.$m224$,'41307f8210164de916a7242e92bd0327',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(29,0,1,$m224$تلتزم الشركة بإتمام قيد الأوراق المالية، وبالرد على استفسارات مصدريها وغيرهم من ذوي المصلحة خلال المدة ووفقا للأوضاع التي تحددها اللائحة التنفيذية.
وعلى الشركة أن تمسك الدفاتر والسجلات وتعد التقارير اللازمة لمباشرة نشاطها وفقا لما تحدده اللائحة التنفيذية.$m224$,'8800e836da0f657de38b49225cecdc5e',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(30,0,1,$m224$لا يجوز لغير البنوك والجهات التي تحددها اللائحة التنفيذية أن تمارس نشاط أمناء الحفظ. ويصدر بالترخيص بممارسة هذا النشاط قرار من الهيئة وفقا للقواعد والإجراءات التي تحددها هذه اللائحة.
ويقصد بنشاط أمناء الحفظ كل نشاط يتناول حفظ الأوراق المالية والتعامل عليها، وإدارتها باسم ولصالح المالك أو باسم المالك المسجل لصالح المالك المستفيد، وذلك كله تنفيذا لتعليمات العميل وفي حدودها$m224$,'bb42d2fb750a295acd009a1df5a83d0b',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(31,0,1,$m224$يلتزم المرخص له بممارسة نشاط أمناء الحفظ بما يأتي:
1 - الفصل بين الأوراق المالية والحسابات الخاصة به وبين ما يخص كل من عملائه، مع إمساك سجلات بذلك.
2 - إضافة وخصم المدفوعات الناتجة عن التعامل على الأوراق المالية وإدارتها في الحساب الخاص بكل عميل.
3 - رد الأوراق المالية للعميل وما له من مبالغ نقدية وذلك بناء على طلبه.$m224$,'b504f1a14211ad58db7a6fa3a5d06442',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(32,0,1,$m224$على المرخص له بممارسة نشاط أمناء الحفظ أن يبرم اتفاقا مكتوبا مع كل من عملائه بما لا يتعارض مع القواعد والأحكام التي تضعها الهيئة.$m224$,'a1d3c94ed2d98f2d263853bfa6d4d2f9',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(33,0,1,$m224$مع عدم الإخلال بالأحكام المنصوص عليها في هذا القانون، يكون تأسيس الشركة في شكل شركة مساهمة لمزاولة أوجه نشاطها وفقا للأحكام الخاصة بالشركات العاملة في مجال الأوراق المالية والمنصوص عليها في قانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992، ويكون نظامها الأساسي وفقا للنموذج المعد من الهيئة لهذا الغرض.
ويكون لجهات الإيداع المركزي الأجنبية أن تتمتع بصفة العضوية دون أن تلتزم بالمساهمة في الشركة، وذلك وفقا للأحكام التي تحددها اللائحة التنفيذية لهذا القانون.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'f97a85bf43a28922cfbd127086723314',DATE '2020-07-10',NULL,'active',143,2020,$m224$عُدّلت بالقانون رقم 143 لسنة 2020 (النص الوارد هو النص بعد التعديل؛ النص الأصلى قبل التعديل غير وارد فى المصدر). تاريخ نفاذ التعديل مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(34,0,1,$m224$تتخذ الشركة شكل شركة مساهمة، ولا يقل رأس مالها المصدر والمدفوع منه عما تحدده اللائحة التنفيذية. ويتكون رأس مال الشركة من أسهم اسمية من ذات النوع والقيمة.$m224$,'c079fbec403170ab77062113052f8b2a',DATE '2000-07-01',DATE '2020-07-09','amended',143,2020,$m224$النص قبل الإلغاء بالقانون رقم 143 لسنة 2020 كما ورد فى النسخة المحدثة للهيئة.$m224$),
(34,0,2,$m224$ملغاة.
*ألغيت بموجب قانون رقم 143 لسنة 2020.$m224$,'8e4cbae06576571d408855984a97425a',DATE '2020-07-10',NULL,'repealed',143,2020,$m224$ألغيت بالقانون رقم 143 لسنة 2020. تاريخ النفاذ مسجل تقريبياً.$m224$),
(35,0,1,$m224$على الشركة التي تطلب الترخيص لها بمزاولة نشاطي الإيداع والقيد المركزي في مصر أن ترفق بطلب الترخيص نسخة من القواعد والإجراءات الداخلية التي ستتبعها في مزاولة هذا النشاط بالإضافة إلى ما تطلبه الهيئة من مستندات وبيانات إضافية.
وعلى الهيئة عند إصدار قرارها في طلب الترخيص مراعاة احتياجات سوق رأس المال وما يحقق صالحه.
ويجوز أن يقتصر الترخيص على نوع أو أكثر من الأوراق المالية أو على نطاق جغرافي معين وأن يشتمل على أية شروط تتصل بمزاولة النشاط.$m224$,'e718474748327b712c5029f0067a412c',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(35,1,1,$m224$للبنك المركزي المصري أن يباشر من خلال شركة مساهمة مملوكة له بالكامل أو بالمشاركة مع الغير، نشاطي الإيداع والقيد المركزي بالنسبة للأدوات والأوراق المالية الحكومية. ويتم تأسيس الشركة وفقا للأحكام الخاصة بالشركات العاملة في مجال الأوراق المالية المنصوص عليها في قانون سوق رأس المال المشار إليه، وذلك دون التقيد بالأحكام الواردة بهذا الفصل.
ويصدر مجلس إدارة الهيئة القواعد المنظمة لإيداع وقيد الأدوات والأوراق المالية الحكومية وتسوية المراكز المالية الناشئة عن تداولها بما في ذلك الحالات التي يتم فيها إنشاء صندوق لضمان الوفاء بالالتزامات الناشئة عن العمليات التي تقوم بها الشركة والقواعد المنظمة له، وذلك كله بعد أخذ رأي البنك المركزي المصري ووزارة المالية.
وتسري الأحكام المنصوص عليها في هذا القانون على عمليات الإيداع والقيد المركزي للأدوات والأوراق المالية الحكومية وعلى أعضاء الإيداع المركزي وأمناء الحفظ وذلك فيما لم يرد في شأنه نص خاصة في القواعد الصادرة وفقا لحكم الفقرة الثانية من هذه المادة.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'274218d77befa481dee0f34a0bbcd7fa',DATE '2020-07-10',NULL,'active',143,2020,$m224$أضيفت بالقانون رقم 143 لسنة 2020. تاريخ النفاذ مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(35,2,1,$m224$يكون تأسيس الشركات التي تقوم بإجراءات عمليات المقاصة والتسوية للعقود التي يجرى التعامل عليها في بورصات العقود الآجلة وفقا للأحكام الخاصة بالشركات العاملة في مجال الأوراق المالية والمنصوص عليها في قانون سوق رأس المال المشار إليه، على أن تكون في شكل شركة مساهمة، وترخص لها الهيئة بالقيام بتلك الأنشطة، ويكون نظامها الأساسي وفقا للنموذج المعد من الهيئة لهذا الغرض، وذلك دون التقيد بالأحكام الواردة بهذا الفصل.
وفي حالة التسوية المادية للعقود على السلع، يتم تسليم السلع محل العقود وفقا للقواعد التي تضعها وحدة الإشراف والرقابة على المخازن المعتمدة للسلع المشار إليها بالمادة (26 مكررا 6) من قانون سوق رأس المال.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'d6cd90079d41841930f768813cf4653a',DATE '2020-07-10',NULL,'active',143,2020,$m224$أضيفت بالقانون رقم 143 لسنة 2020. تاريخ النفاذ مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(35,3,1,$m224$تصدر الشركة المرخص لها بإجراء عمليات المقاصة والتسوية للعقود الآجلة لائحة بقواعد وإجراءات المقاصة والتسوية، ولا تكون هذه اللائحة نافذة إلا بعد اعتمادها من الهيئة.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'af0a35a957c9b8a8bf34da793faae083',DATE '2020-07-10',NULL,'active',143,2020,$m224$أضيفت بالقانون رقم 143 لسنة 2020. تاريخ النفاذ مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(36,0,1,$m224$على الشركة أن تنشئ إدارة خاصة لكل من نشاط الإيداع المركزي ونشاط القيد المركزي ولصندوق ضمان التسوية، ويكون لكل إدارة حسابات مستقلة ومركز مالي خاص.$m224$,'34d59a0e6db97e6688afc8107d853fe5',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(37,0,1,$m224$تكون أسهم شركة الإيداع والقيد المركزي للأوراق المالية مملوكة لبورصات الأوراق المالية المصرية ولأعضاء الإيداع المركزي، وتكون نسبة مساهمة عضو الإيداع المركزي على نحو يناسب حجم تعاملاته مع الشركة وفقا لما يسدده لها من أتعاب ومصروفات، وبشرط ألا تجاوز ملكية العضو أو أي مجموعة مرتبطة نسبة (5%) من رأسمال الشركة، ويحدد النظام الأساسي للشركة نسبة ما تمتلكه بورصات الأوراق المالية بشرط ألا تقل عن (5%) من رأسمال الشركة، وتمثل بعضو واحد على الأقل في مجلس إدارة الشركة. ويتم نقل ملكية الأسهم بين أعضاء الإيداع المركزي والبورصات بقرار من الجمعية العمومية غير العادية للشركة طبقا لنظامها الأساسي، ولا يجوز التصرف في هذه الأسهم إلا في حالة إعادة التوزيع، أو إذا زالت صفة العضوية في الإيداع المركزي.
ويتم نقل ملكية الأسهم في هذه الحالات إلى الشركة لتعيد توزيعها وفقا لما تحدده اللائحة التنفيذية لهذا القانون، ويقع باطلا كل تصرف يتم على خلاف ذلك.
وتحدد اللائحة التنفيذية لهذا القانون قواعد توزيع الحصص في رأسمال الشركة عند تأسيسها وعند قبول أعضاء جدد بها، والقواعد التي تنظم إعادة توزيع الأسهم فيما بين الأعضاء تنفيذا لأحكام الفقرة الأولى من هذه المادة، ويتم نقل ملكية الأسهم بين الأعضاء أو بينهم وبين الشركة وفقا لقيمتها الاسمية.
ويكون لجهات الإيداع المركزي الأجنبية أن تتمتع بصفة العضوية دون أن تلتزم بالمساهمة في الشركة، وذلك وفقا للأحكام التي تحددها اللائحة التنفيذية لهذا القانون.
ويقصد بالمجموعة المرتبطة كل مجموعة من الأعضاء تكون خاضعة للسيطرة الفعلية لنفس الأشخاص الطبيعيين أو لذات الأشخاص الاعتبارية، أو يجمع بينها اتفاق على التنسيق عند التصويت في اجتماعات الجمعية العامة للشركة أو في مجلس إدارتها.
ويحدد مجلس إدارة الهيئة شروط وضوابط وإجراءات الترخيص بمزاولة النشاط للشركات المنصوص عليها في هذا الفصل، والحد الأدنى لرأسمالها المصدر والمدفوع بالكامل بما لا يقل عن خمسين مليون جنيه، والحدود القصوى لمقابل الخدمات التي تقدمها.
ويصدر مجلس إدارة الهيئة قرارا بتحديد فئات رسوم الترخيص للشركات المشار إليها في الفقرة السابقة بما لا يجاوز مائة ألف جنيه، وتسدد الرسوم نقدا أو بإحدى وسائل الدفع غير النقدي المنصوص عليها بقانون تنظيم استخدام وسائل الدفع غير النقدي الصادر بالقانون رقم 18 لسنة 2019.
*معدلة بموجب قانون رقم 143 لسنة 2020.
*معدلة بموجب قانون رقم 127 لسنة 2009.$m224$,'ed76bf969b101850681b809f2a064452',DATE '2020-07-10',NULL,'active',143,2020,$m224$عُدّلت بالقانون رقم 143 لسنة 2020 (النص الوارد هو النص بعد التعديل؛ النص الأصلى قبل التعديل غير وارد فى المصدر). تاريخ نفاذ التعديل مسجل تقريبياً (القانون صدر فى يوليو 2020). عُدّلت أيضاً بالقانون رقم 127 لسنة 2009.$m224$),
(38,0,1,$m224$لا يجوز التصرف في أسهم الشركة إلا في حالة إعادة توزيع الأسهم المنصوص عليها في المادة (37) من هذا القانون، أو إذا زالت صفة العضوية في الإيداع المركزي.
ويتم نقل ملكية الأسهم في هذه الحالات إلى الشركة لتعيد توزيعها وفقا لما تحدده اللائحة التنفيذية، ويقع باطلا كل تصرف يتم على خلاف ذلك.$m224$,'7953a303369028fc8ff99b96a59281c6',DATE '2000-07-01',DATE '2020-07-09','amended',143,2020,$m224$النص قبل إلغاء الفقرة الأولى بالقانون رقم 143 لسنة 2020 كما ورد فى النسخة المحدثة للهيئة.$m224$),
(38,0,2,$m224$ويتم نقل ملكية الأسهم في هذه الحالات إلى الشركة لتعيد توزيعها وفقا لما تحدده اللائحة التنفيذية، ويقع باطلا كل تصرف يتم على خلاف ذلك.
*الفقرة الأولى ألغيت بموجب قانون رقم 143 لسنة 2020.$m224$,'6cb85e36b8c57ea66d99c798dd9e3089',DATE '2020-07-10',NULL,'active',143,2020,$m224$ألغيت الفقرة الأولى بالقانون رقم 143 لسنة 2020. تاريخ النفاذ مسجل تقريبياً.$m224$),
(39,0,1,$m224$يفقد عضو الإيداع المركزي صفة العضوية في الحالات الآتية:
1 - إفلاس العضو أو زوال شخصيته القانونية.
2 - إلغاء ترخيص مزاولة العضو للنشاط المرخص له به من الهيئة.
3 - إلغاء العضوية بقرار من الهيئة بسبب مخالفة العضو لأحكام هذا القانون أو القرارات الصادرة تنفيذا له.
4 - إلغاء العضوية بقرار من الجمعية العامة غير العادية للشركة يصدر بأغلبية ثلاثة أرباع الأعضاء الحاضرين.$m224$,'c633806cae82998b12b6928e284edcd1',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(40,0,1,$m224$لا يجوز للشركة أن تتقاضى مقابلا عن الخدمات التي تقدمها يزيد على الحدود التي يصدر بها قرار من الوزير المختص.
وإذا أسفر نشاط الشركة عن تحقيق أرباح، جاز تخصيص جزء منها لتمويل صندوق ضمان التسوية المنصوص عليه في المادة (18) من هذا القانون، ورد ما يتبقى للمساهمين في الشركة ولمصدري الأوراق المالية وفقا للقواعد التي تحددها اللائحة التنفيذية.$m224$,'4f3f0da34ed3abd99771c45980207204',DATE '2000-07-01',DATE '2020-07-09','amended',143,2020,$m224$النص قبل الإلغاء بالقانون رقم 143 لسنة 2020 كما ورد فى النسخة المحدثة للهيئة.$m224$),
(40,0,2,$m224$ملغاة.
*ألغيت بموجب قانون رقم 143 لسنة 2020.$m224$,'8e4cbae06576571d408855984a97425a',DATE '2020-07-10',NULL,'repealed',143,2020,$m224$ألغيت بالقانون رقم 143 لسنة 2020. تاريخ النفاذ مسجل تقريبياً.$m224$),
(41,0,1,$m224$لمجلس إدارة الهيئة إلغاء الترخيص بمزاولة نشاطي الإيداع والقيد المركزي بسبب مخالفة الشركة لأحكام هذا القانون أو القرارات الصادرة تنفيذا له، إذا كان من شأن المخالفة إلحاق الضرر بسوق رأس المال أو تهديد استقراره، وذلك بعد إخطار الشركة بالمخالفة المنسوبة إليها وإعطائها مهلة مناسبة لتصحيح المخالفة أو إبداء دفاعها في شأنها.
ويجب أن يتضمن قرار إلغاء الترخيص الإجراءات والترتيبات اللازمة لمواجهة آثار الإلغاء ولا يكون القرار نافذا إلا بعد اعتماده من الوزير المختص.
وتحدد اللائحة التنفيذية القواعد والإجراءات التي تتبع في هذا الخصوص.$m224$,'1b5ecd9e4238cc5fd49df7aca71a8f30',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(42,0,1,$m224$تقوم الهيئة بمراقبة الشركة والتفتيش على أعمالها وفقا للأحكام الخاصة بالشركات العاملة في مجال الأوراق المالية والمنصوص عليها في قانون سوق رأس المال المشار إليه.$m224$,'a2a77c192403ff4e603ec61306c3e9cf',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(43,0,1,$m224$على الشركة القيام بما يأتي:
1 - الاستعانة بنظم وإجراءات ملائمة وكافية لحماية الأوراق المالية المحفوظة لديها.
2 - الاستعانة بمحاسبين قانونيين من خارج الشركة لتقييم أساليب المراجعة المالية لديها.
3 - إعداد تقارير دورية عن أداء الشركة يخطر بها أعضاء الإيداع المركزي ومصدرو الأوراق المالية.
4 - وضع ترتيبات لضمان حسن أداء نظام المعالجة الإلكتروني للمعلومات ونظام استرجاع المعلومات المحفوظة به في حال تعطله.$m224$,'d1664800ab43492a8c10b2174369c026',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(44,0,1,$m224$تضع الشركة النظم الفنية لعمليات الإيداع والمقاصة والتسوية والقيد المركزي وغيرها من النظم المرتبطة بالتداول في سوق الأوراق المالية والرقابة عليها بعد موافقة مجلس إدارة الهيئة العامة للرقابة المالية.
*معدلة بموجب قانون رقم 127 لسنة 2009.$m224$,'ce22ca4ce583e3baa88dba3ba4851f8a',DATE '2000-07-01',NULL,'active',127,2009,$m224$عُدّلت بالقانون رقم 127 لسنة 2009 (النص الوارد هو النص بعد التعديل). تاريخ نفاذ التعديل غير وارد فى المصدر فسُجل تاريخ نفاذ القانون الأصلى.$m224$),
(45,0,1,$m224$يتولى مراجعة حسابات الشركة مراقبان للحسابات يتم اختيارهما من بين المقيدين في سجل تمسكه الهيئة لهذا الغرض.
وعلى الشركة أن تقدم للهيئة التقارير والقوائم المالية التي تلتزم بتقديمها الشركات التي تطرح أوراقا مالية في اكتتاب عام عملا بأحكام قانون سوق رأس المال المشار إليه، بالإضافة إلى التقارير الأخرى التي تحددها اللائحة التنفيذية.$m224$,'66c1c062161e24cce9e12a979f2c1ffe',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(46,0,1,$m224$دون الإخلال بسلطة الجمعية العامة للشركة في اختيار أعضاء مجلس إدارتها تكون غالبية هؤلاء الأعضاء من ذوي الخبرة على أن يكون من بينهم كل من رئيس مجلس الإدارة والعضو المنتدب.
وتعرض قائمة المرشحين لرئاسة وعضوية مجلس إدارة الشركة بعد موافقة مجلس إدارة الهيئة العامة للرقابة المالية على الجمعية العامة للاختيار من بينها، كما يتم بموافقة مجلس إدارة هذه الهيئة تعيين المديرين التنفيذيين المسئولين عن المقاصة والتسوية والإيداع المركزي وصندوق ضمان التسوية.
*معدلة بموجب قانون رقم 127 لسنة 2009.$m224$,'e04bf6ec35513125451e6af41d8a972f',DATE '2000-07-01',NULL,'active',127,2009,$m224$عُدّلت بالقانون رقم 127 لسنة 2009 (النص الوارد هو النص بعد التعديل). تاريخ نفاذ التعديل غير وارد فى المصدر فسُجل تاريخ نفاذ القانون الأصلى.$m224$),
(47,0,1,$m224$لمجلس إدارة الهيئة حفاظا على استقرار سوق رأس المال وحسن سير أعمال الشركة أن يصدر قرارا مسببا باستبعاد عضو أو أكثر من أعضاء مجلس الإدارة، كما له تعيين عضو مراقب بمجلس إدارة الشركة وذلك للمدة التي يحددها مجلس إدارة الهيئة، ويكون لهذا العضو المشاركة في مناقشات المجلس وتسجيل رأيه فيما يتخذ من قرارات دون أن يكون له حق التصويت.$m224$,'0a1598372c1f8aa80827825cad08f7bb',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(48,0,1,$m224$تكون الشركة مسئولة عن الضرر الناجم عن:
1 - عدم تسليم الأوراق المالية أو تحويل الأموال التي تخص العضو أو أي من عملائه أو عدم قيد أو نقل ملكية الأوراق المالية.
2 - فقد الأوراق المالية أو الأموال.
3 - أي ضرر آخر يلحق بالعضو أو بأي من عملائه أو بمصدري الأوراق المالية أو بالغير والذي تكون الشركة مسئولة عنه وفقا لنظامها الأساسي أو للإجراءات والقواعد المتبعة لديها أو للاتفاق الذي ينظم علاقتها مع العضو أو مع مصدر الأوراق المالية.
ويتحمل الأعضاء جبر الضرر الناجم عن مسئولية الشركة وفقا للقواعد التي تضعها بشأن المشاركة في تحمل تلك المسئولية، وذلك ما لم يكن الضرر مؤمنا عليه.$m224$,'7d0b1b7e5472d723f72aad054796eca8',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(49,0,1,$m224$يجب أن تتوافر لدى الشركة الوسائل والإجراءات الكفيلة بالحفاظ على سرية المعلومات التي تخص المعاملات التي تتم من خلالها، وبضمان عدم قيام أي من مديريها أو العاملين بها أو وكلائها بإفشاء تلك المعلومات، كما يلزم أن يكون لدى الشركة وسائل ملائمة لكشف من يخالف تلك الإجراءات والقواعد.
ويجوز لعضو الإيداع المركزي ولمصدر الأوراق المالية أن يطلب الاطلاع على دفاتر الشركة وسجلاتها التي تتعلق بمعاملاته معها، وعلى الشركة أن تمكنه هو أو من يعينه من الاطلاع على تلك الدفاتر والسجلات في مقرها ومن الحصول على صورة منها.$m224$,'3df0b7bf1796f230605cb4ddeb97f328',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(50,0,1,$m224$يضع مجلس إدارة الهيئة القواعد الخاصة بالتدابير التي تتخذها بالنسبة إلى الشركة في حالات مخالفة أحكام هذا القانون والقرارات الصادرة تنفيذا له، ولا تكون هذه القرارات نافذة إلا بعد اعتمادها من الوزير المختص.$m224$,'e1d33fdc29de73a7182079676e0f36c6',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(51,0,1,$m224$تسري أحكام قانون سوق رأس المال المشار إليه بشأن من لهم صفة الضبطية القضائية وسلطاتهم في إثبات الجرائم التي تقع بالمخالفة لأحكام هذا القانون والقرارات الصادرة تنفيذا له.$m224$,'360204029964ee1117accd5fe9fe7595',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(51,1,1,$m224$مع مراعاة أحكام قانون التجارة الصادر بالقانون رقم 17 لسنة 1999، تسري الأحكام الواردة في هذا الفصل على رهن الأوراق والأدوات المالية والأوراق والأدوات المالية الحكومية.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'25f1bb454ed80d55fcf96be97a4ab24b',DATE '2020-07-10',NULL,'active',143,2020,$m224$أضيفت بالقانون رقم 143 لسنة 2020. تاريخ النفاذ مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(51,2,1,$m224$يكون اتفاق رهن الأوراق أو الأدوات المالية وفقا لأحكام هذا القانون ملزما ونافذا في مواجهة الغير متى كان مكتوبا وثابت التاريخ ومتضمنا تحديد محل الرهن، ويكفي لتحديد الرهن أن يتم قيده في حساب الراهن لدى الشركة.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'208d181d02865ca184caeee8a6c5e4d3',DATE '2020-07-10',NULL,'active',143,2020,$m224$أضيفت بالقانون رقم 143 لسنة 2020. تاريخ النفاذ مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(51,3,1,$m224$للمدين الراهن للأوراق أو الأدوات المالية الحق في استغلالها متى كان اتفاق الرهن ينص على ذلك وبشرط أن يلتزم باستبدالها بأوراق أو أدوات مالية أخرى لا تقل في القيمة أو الشروط عن الأوراق أو الأدوات المرهونة قبل حلول أجل الالتزام المضمون بالرهن، ولا يخل ذلك بكافة حقوق الدائن المرتهن على الأوراق أو الأدوات المالية وفقا لاتفاق الرهن بما في ذلك الحق في التنفيذ على الأوراق أو الأدوات المرهونة أو تلك التي تم استبدالها بها.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'a60dc695be2f1fb9269ea201fdaf4036',DATE '2020-07-10',NULL,'active',143,2020,$m224$أضيفت بالقانون رقم 143 لسنة 2020. تاريخ النفاذ مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(51,4,1,$m224$يكون للدائن المرتهن للأوراق أو الأدوات المالية عند تحقق الواقعة المنشئة لحقه في التنفيذ، وبعد مضي خمسة أيام من تكليف المدين بالوفاء بموجب كتاب مسجل مصحوب بعلم الوصول، أن يباشر ذلك عن طريق بيعها أو الاستحواذ عليها مع خصم قيمتها من مستحقاته المالية.
ومع ذلك لا يجوز الاستحواذ مباشرة على الأوراق أو الأدوات المالية إلا إذا نص اتفاق الرهن على ذلك وعلى أسلوب تقييم الأوراق أو الأدوات المالية بغرض التنفيذ.
وفي جميع الأحوال، لا يجوز الاتفاق على إرجاء التنفيذ على الأوراق أو الأدوات المالية المرهونة لحين صدور قرار إداري أو حكم قضائي أو إجراء مزاد أو لحين انقضاء فترة زمنية معينة، كما لا يترتب على إفلاس المدين الراهن أو الدائن المرتهن أو إعادة هيكلته إرجاء التنفيذ.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'5ea725116f4873c7902cf82197f31e9a',DATE '2020-07-10',NULL,'active',143,2020,$m224$أضيفت بالقانون رقم 143 لسنة 2020. تاريخ النفاذ مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(51,5,1,$m224$يكون اتفاق رهن الأوراق أو الأدوات المالية وما يرتبط به من رهون إضافية أو استبدال لمحل الرهن ساريا ونافذا تجاه الكافة متى انعقد قبل بدء إجراءات تصفية أو إعادة هيكلة المدين الراهن أو يوم بدء تلك الإجراءات بشرط إثبات المدين الراهن عدم علمه بها.
*مضافة بموجب قانون رقم 143 لسنة 2020.$m224$,'a68f9ebad223b02f98fe4e08653f9495',DATE '2020-07-10',NULL,'active',143,2020,$m224$أضيفت بالقانون رقم 143 لسنة 2020. تاريخ النفاذ مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(52,0,1,$m224$تكون جميع القيود والعمليات التي تمت وأصبحت نهائية وفقا للقواعد المعتمدة من مجلس إدارة الهيئة سارية، ولا يجوز وقفها أو إبطالها أو الحجز عليها وذلك دون التقيد بالأحكام المنصوص عليها في أي قانون آخر.
وفي حالة إفلاس أحد أعضاء الإيداع المركزي تقوم الشركة بإتمام المقاصة والتسوية للعمليات التي كان طرفا فيها والمراكز المالية الناشئة عن الأوامر النهائية الصادرة منه قبل إخطار الشركة بحكم شهر إفلاسه، وتكون تلك العمليات والأوامر نافذة في مواجهة الكافة.
ومع عدم الإخلال بنهائية العملية، يجوز للهيئة من تلقاء نفسها أو بناء على طلب أمين التفليسة أو أحد ذوي المصلحة، أن تعكس قيد تلك العمليات إذا تبين لها أنها تمت بناء على غش أو تدليس أو نتيجة لخطأ أو إهمال أو سوء نية من الشركة أو من أحد أعضاء الإيداع المركزي.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'037843b0886c16c5a81b2ee9e16b8c4d',DATE '2020-07-10',NULL,'active',143,2020,$m224$عُدّلت بالقانون رقم 143 لسنة 2020 (النص الوارد هو النص بعد التعديل؛ النص الأصلى قبل التعديل غير وارد فى المصدر). تاريخ نفاذ التعديل مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(53,0,1,$m224$تسري أحكام المادتين (50) و(51) من قانون سوق رأس المال المشار إليه على التظلمات التي يقدمها أصحاب الشأن من القرارات التي تصدر من الوزير المختص أو من الهيئة تطبيقا لأحكام هذا القانون والقرارات الصادرة تنفيذا له.$m224$,'b88ddf206e3686f053092e6ab1a1bc8b',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(54,0,1,$m224$مع عدم الإخلال بأية عقوبة أشد منصوص عليها في أي قانون آخر، يعاقب بالحبس مدة لا تقل عن سنة وبغرامة لا تقل عن مائة ألف جنيه ولا تزيد على مائتي ألف جنيه أو بإحدى هاتين العقوبتين كل من باشر نشاطا من الأنشطة الخاضعة لأحكام هذا القانون دون أن يكون مرخصا له في ذلك.$m224$,'ee5d90d512e8d6e14649271bac3290e7',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(55,0,1,$m224$مع عدم الإخلال بأي عقوبة أشد منصوص عليها في أي قانون آخر، يعاقب بغرامة لا تقل عن خمسين ألف جنيه ولا تزيد على مائة ألف جنيه كل من خالف أحكام الفقرة الثالثة من المادة (8) والمواد (10, 28, 31, 43, 46) من هذا القانون.
ويجوز أن تتضمن القرارات الصادرة عن مجلس إدارة الهيئة تطبيقا لأحكام هذا القانون تقرير عقوبة الغرامة لكل من يخالفها، على أن ينشر القرار في الوقائع المصرية وألا تقل الغرامة عن عشرة آلاف جنيه ولا تزيد على خمسين ألف جنيه.
*معدلة بموجب قانون رقم 143 لسنة 2020.$m224$,'68f7e3b5335ffa5a54f62d920c111386',DATE '2020-07-10',NULL,'active',143,2020,$m224$عُدّلت بالقانون رقم 143 لسنة 2020 (النص الوارد هو النص بعد التعديل؛ النص الأصلى قبل التعديل غير وارد فى المصدر). تاريخ نفاذ التعديل مسجل تقريبياً (القانون صدر فى يوليو 2020).$m224$),
(56,0,1,$m224$مع عدم الإخلال بأية عقوبة أشد منصوص عليها في أي قانون آخر، يعاقب بالحبس مدة لا تقل عن ستة أشهر وبغرامة لا تقل عن خمسين ألف جنيه ولا تزيد على مائة ألف جنيه أو بإحدى هاتين العقوبتين كل من أفشى سرا اتصل به بحكم عمله تطبيقا لأحكام هذا القانون أو حقق نفعا منه بطريق مباشر أو غير مباشر.$m224$,'29f483c4302c4260a98d9a145023d8fa',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(57,0,1,$m224$يجوز فضلا عن العقوبات المقررة للجرائم المنصوص عليها في المواد السابقة الحكم بالحرمان من مزاولة المهنة أو بحظر مزاولة النشاط الذي وقعت الجريمة بمناسبته، وذلك لمدة لا تزيد على ثلاث سنوات، ويكون الحكم بذلك وجوبيا في حالة العود.$m224$,'d9f5bcafff1331783655eccf34194f1d',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(58,0,1,$m224$يعاقب المسئول عن الإدارة الفعلية بالشركة المخالفة بذات العقوبات المقررة عن الأفعال التي ترتكب بالمخالفة لأحكام هذا القانون إذا ثبت علمه بها وكان إخلاله بالواجبات التي تفرضها عليه تلك الإدارة قد أسهم في وقوع الجريمة.
وتكون الشركة مسئولة بالتضامن عن الوفاء بما يحكم به من عقوبات مالية إذا كانت المخالفة قد ارتكبت من أحد العاملين بالشركة باسمها أو لصالحها.$m224$,'9c53a5706254e618572602ca233b0a86',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL),
(59,0,1,$m224$لا ترفع الدعوى الجنائية بالنسبة للجرائم المنصوص عليها في هذا القانون إلا بناء على طلب كتابي من الوزير المختص بعد أخذ رأي رئيس الهيئة.
ويجوز للوزير المختص التصالح مع المتهم أو المحكوم عليه في أي من تلك الجرائم مقابل أداء مبلغ للهيئة لا يقل عن الحد الأقصى للغرامة ولا يجاوز ضعفه بالإضافة إلى قيمة ما عاد على المتهم من نفع أو ما سببه من ضرر بسبب الجريمة أيهما أكبر، ويترتب على التصالح انقضاء الدعوى الجنائية.
وتأمر النيابة العامة بوقف تنفيذ عقوبة الحبس إذا تم الصلح أثناء تنفيذها ولو بعد صيرورة الحكم باتًا$m224$,'ce4b15a1ce5ddb5ddadc8cbaddd2b6a3',DATE '2000-07-01',NULL,'active',NULL,NULL,NULL);

DO $m224$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m224_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m224_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[224] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m224_art) <> 74 OR (SELECT sum(char_length(body)) FROM m224_art) <> 27176 OR (SELECT count(*) FROM m224_ver) <> 77 THEN
    RAISE EXCEPTION '[224] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=93 AND law_year=2000 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%الإيداع%' THEN
    RAISE EXCEPTION '[224] يوجد مستند آخر برقم 93 لسنة 2000 (%): لا يُدمج هذا القانون فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (93, 2000, $t224$القانون رقم 93 لسنة 2000 بإصدار قانون الإيداع والقيد المركزى للأوراق المالية (النسخة المحدثة للهيئة العامة للرقابة المالية بعد تعديل القانون 143 لسنة 2020)$t224$, $t224$قانون الإيداع والقيد المركزى للأوراق المالية 93/2000$t224$, 'capital_markets', 'amended', NULL, DATE '2000-05-18', DATE '2020-07-10', 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m224_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m224_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m224_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 74 THEN
    RAISE EXCEPTION '[224] عدد صفوف القانون % بدل 74', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 77 THEN
    RAISE EXCEPTION '[224] عدد نسخ القانون % بدل 77', v_vcnt;
  END IF;
  RAISE NOTICE '[224] قانون 93/2000: جديد=%، صفوف مضافة=%، نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m224$;
